/* generado por prompts/herramientas/clave-tests.js; no editar a mano */
(window.CLAVE_TEST=window.CLAVE_TEST||{})[1]=[{"a":"Artículos 5 y 6 — Crímenes de la competencia de la Corte y genocidio ✱ R19","q":[{"i":"1-95","p":"Estatuto de Roma de la Corte Penal Internacional. La Corte tendrá competencia, de conformidad con el presente Estatuto, respecto de los siguientes crímenes: señale la INCORRECTA.","o":["El crimen de genocidio.","Los crímenes de lesa humanidad.","Los crímenes de guerra.","El crimen de terrorismo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El crimen de terrorismo.</mark></span>El <span class=\"ref-norma\">art. 5.1 de el Estatuto de Roma de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"La Corte tendrá competencia, de conformidad con el presente Estatuto, respecto de los siguientes crímenes: a) El crimen de genocidio; b) Los crímenes de lesa humanidad; c) Los crímenes de guerra; d) El crimen de agresión\"</span>."},{"i":"1-ia-3740","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Condiciones previas para el ejercicio de la competencia. El Estado que pase a ser Parte en el Estatuto acepta por ello la competencia de la Corte respecto a los crímenes a que se refiere:","o":["la competencia material de la Corte limitada a los crímenes que declare expresamente.","la competencia material de la Corte: genocidio, lesa humanidad, guerra y agresión.","la competencia material de la Corte respecto de los crímenes cometidos en su territorio.","la competencia material de la Corte respecto de los crímenes cometidos por sus nacionales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la competencia material de la Corte: genocidio, lesa humanidad, guerra y agresión</mark></span>El <span class=\"ref-norma\">art. 12.1 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"acepta por ello la competencia de la Corte res-peto a los crímenes a que se refiere el artículo 5\"</span>. La aceptación es automática para los crímenes del artículo 5. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3634","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de la competencia de la Corte. La competencia de la Corte se limitará a los crímenes más graves de trascendencia para la comunidad internacional en su conjunto. La Corte tendrá competencia respecto de los siguientes crímenes: el crimen de genocidio, los crímenes de lesa humanidad, los crímenes de guerra y:","o":["el crimen de terrorismo internacional.","el crimen de piratería.","el crimen de tráfico ilícito de estupefacientes.","el crimen de agresión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el crimen de agresión</mark></span>El <span class=\"ref-norma\">art. 5.1 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"c) Los crímenes de guerra; d) El crimen de agresión\"</span>. Los cuatro crímenes son genocidio, lesa humanidad, guerra y agresión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3635","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Genocidio. A los efectos del Estatuto, se entenderá por «genocidio» cualquiera de los actos perpetrados con la intención de destruir total o parcialmente a un grupo:","o":["nacional, étnico, racial, religioso o político como tal.","étnico, racial, cultural o religioso como tal.","nacional, étnico, racial o religioso como tal.","nacional, étnico o religioso, o a un grupo social determinado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">nacional, étnico, racial o religioso como tal</mark></span>El <span class=\"ref-norma\">art. 6 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"perpetrados con la intención de destruir total o parcialmente a un grupo nacional, étnico, racial o religioso como tal\"</span>. Los grupos protegidos son nacional, étnico, racial o religioso; no el político. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-147","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Genocidio (PREGUNTA EXAMEN 2020). A los efectos del Estatuto de Roma, se entenderá por «genocidio» cualquiera de los actos mencionados a continuación, perpetrados con la intención de destruir total o parcialmente a un grupo nacional, étnico, racial o religioso como tal, entre ellos:","o":["el traslado por la fuerza de niños del grupo a otro grupo.","la deportación de miembros del grupo a otro territorio.","la persecución del grupo por motivos políticos o religiosos.","el desplazamiento forzoso de la población civil del grupo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el traslado por la fuerza de niños del grupo a otro grupo</mark></span>El <span class=\"ref-norma\">art. 6 de el Estatuto de Roma de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"e) Traslado por la fuerza de niños del grupo a otro grupo\"</span>. El traslado forzoso que es genocidio es el de niños del grupo a otro grupo."},{"i":"1-ia-3638","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Genocidio. Constituyen también genocidio las medidas destinadas a impedir nacimientos en el seno del grupo y:","o":["la separación forzosa de las familias del grupo.","la esterilización forzada de los miembros del grupo.","el traslado forzoso de población del grupo a otro territorio.","el traslado por la fuerza de niños del grupo a otro grupo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el traslado por la fuerza de niños del grupo a otro grupo</mark></span>El <span class=\"ref-norma\">art. 6.d y e de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"Traslado por la fuerza de niños del grupo a otro grupo\"</span>. El último acto es el traslado por la fuerza de niños del grupo a otro grupo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3636","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Genocidio. Constituye genocidio, entre otros actos, perpetrado con la intención de destruir total o parcialmente a un grupo protegido, la lesión grave:","o":["a la integridad física y a la dignidad de los miembros del grupo.","a la integridad física o mental de los miembros del grupo.","a la integridad moral o psicológica de los miembros del grupo.","a la integridad física, psíquica o sexual de los miembros del grupo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a la integridad física o mental de los miembros del grupo</mark></span>El <span class=\"ref-norma\">art. 6.b de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"Lesión grave a la integridad física o mental de los miembros del grupo\"</span>. La fórmula es «integridad física o mental». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3637","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Genocidio. Constituye genocidio el sometimiento intencional del grupo a condiciones de existencia que hayan de acarrear:","o":["su destrucción física, total o parcial.","su desaparición física y cultural, total o parcial.","su desplazamiento forzoso fuera del territorio que habita.","su debilitamiento económico, social o político."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">su destrucción física, total o parcial</mark></span>El <span class=\"ref-norma\">art. 6.c de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"condiciones de existencia que hayan de acarrear su des-trucción física, total o parcial\"</span>. Las condiciones han de acarrear su destrucción física, total o parcial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 7 y 8 — Lesa humanidad y crímenes de guerra ✱","q":[{"i":"1-ia-3639","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Se entenderá por «crimen de lesa humanidad» cualquiera de los actos enumerados cuando se cometa como parte de un ataque generalizado o sistemático contra una población civil y:","o":["con la intención de destruir a la población civil.","con la autorización de una autoridad estatal.","con conocimiento de dicho ataque.","con ocasión de un conflicto armado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">con conocimiento de dicho ataque</mark></span>El <span class=\"ref-norma\">art. 7.1 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"contra una población civil y con conocimiento de dicho ataque\"</span>. Se exige ataque generalizado o sistemático y conocimiento del ataque; no se exige conflicto armado ni intención genocida. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-148","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad (EX). A los efectos del Estatuto, se entenderá por «crimen de lesa humanidad» cualquiera de los actos siguientes cuando se cometa como parte de un ataque generalizado o sistemático contra una población civil y con conocimiento de dicho ataque:","o":["asesinato, exterminio, esclavitud y deportación o traslado forzoso de población.","asesinato, exterminio y saqueo de bienes de la población civil.","asesinato, tortura y destrucción de bienes no justificada por necesidades militares.","asesinato, esclavitud y el hecho de causar deliberadamente grandes sufrimientos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">asesinato, exterminio, esclavitud y deportación o traslado forzoso de población</mark></span>El <span class=\"ref-norma\">art. 7.1 de el Estatuto de Roma de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"a) Asesinato; b) Exterminio; c) Esclavitud; d) Deportación o traslado forzoso de población\"</span>. El saqueo y la destrucción de bienes son crímenes de guerra."},{"i":"1-201","p":"Estatuto de Roma de la Corte Penal Internacional. Crímenes de lesa humanidad. Señale cuál de los siguientes actos figura expresamente entre los que se entenderán como «crimen de lesa humanidad» cuando se cometan como parte de un ataque generalizado o sistemático contra una población civil y con conocimiento de dicho ataque:","o":["Reclutamiento de niños menores de quince años.","Declaración de que no se dará cuartel.","Ataque contra bienes de carácter civil.","Deportación o traslado forzoso de población."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Deportación o traslado forzoso de población</mark></span>Según el <span class=\"ref-norma\">art. 7.1 del Estatuto de Roma</span>: <span class=\"ref-concepto\">\"Deportación o traslado forzoso de población\"</span>. Los otros tres actos son crímenes de guerra del artículo 8, no de lesa humanidad. <i>(asterisco ✱ del temario)</i><!--t1m:lote1-->"},{"i":"1-ia-3642","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Constituye crimen de lesa humanidad la violación, la esclavitud sexual, la prostitución forzada, el embarazo forzado, la esterilización forzada o cualquier otra forma de violencia sexual:","o":["de especial crueldad.","de carácter sistemático.","que cause lesiones graves.","de gravedad comparable."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de gravedad comparable</mark></span>El <span class=\"ref-norma\">art. 7.1.g de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"cualquier otra forma de violencia sexual de gravedad comparable\"</span>. La cláusula residual exige gravedad comparable. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-202","p":"Estatuto de Roma de la Corte Penal Internacional. Crímenes de lesa humanidad. Persecución. Se entenderá por «crimen de lesa humanidad» la persecución de un grupo o colectividad con identidad propia fundada en motivos políticos, raciales, nacionales, étnicos, culturales, religiosos, de género definido en el párrafo 3, u otros motivos universalmente reconocidos como __________ con arreglo al derecho internacional, en conexión con cualquier acto mencionado en el presente párrafo o con cualquier crimen de la competencia de la Corte.","o":["inaceptables","ilegítimos","discriminatorios","contrarios al orden público"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">inaceptables</mark></span>Según el <span class=\"ref-norma\">art. 7.1.h) del Estatuto de Roma</span>: <span class=\"ref-concepto\">\"u otros motivos universalmente reconocidos como inaceptables con arreglo al derecho internacional\"</span>. La persecución debe estar en conexión con otro acto del artículo 7.1 o con otro crimen de la competencia de la Corte. <i>(asterisco ✱ del temario)</i><!--t1m:lote2-->"},{"i":"1-ia-3643","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Constituye crimen de lesa humanidad la persecución de un grupo o colectividad con identidad propia fundada en motivos políticos, raciales, nacionales, étnicos, culturales, religiosos, de género u otros motivos universalmente reconocidos como inaceptables, siempre que sea:","o":["en conexión con un conflicto armado interno o internacional que afecte al grupo perseguido, conforme al procedimiento que se establezca reglamentariamente.","con la intención de destruir total o parcialmente al grupo perseguido como tal.","en conexión con cualquier acto mencionado en el propio apartado o con cualquier crimen de la competencia de la Corte.","con la aquiescencia o la participación de una autoridad pública o de un grupo organizado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en conexión con cualquier acto mencionado en el propio apartado o con cualquier crimen de la competencia de la Corte</mark></span>El <span class=\"ref-norma\">art. 7.1.h de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"en conexión con cualquier acto mencionado en el presente párrafo o con cualquier crimen de\"</span>. La persecución exige conexión con otro acto de lesa humanidad o crimen de la competencia de la Corte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3644","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Constituyen también crímenes de lesa humanidad la desaparición forzada de personas y:","o":["el crimen de segregación racial.","el crimen de «apartheid».","el crimen de esclavitud económica.","el crimen de discriminación sistemática."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el crimen de «apartheid»</mark></span>El <span class=\"ref-norma\">art. 7.1.i y j de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"Desaparición forzada de personas; j) El crimen de «apartheid»\"</span>. Se menciona expresamente el crimen de «apartheid». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3645","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Por «ataque contra una población civil» se entenderá una línea de conducta que implique la comisión múltiple de actos contra una población civil, de conformidad con:","o":["la política de un Estado o de una organización de cometer ese ataque o para promover esa política.","un plan o una orden de una autoridad militar o civil de cometer ese ataque.","la decisión de un grupo armado organizado que ejerza control sobre un territorio, en los términos que establezca la propia norma.","las instrucciones de un mando superior que ordene cometer actos contra civiles."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la política de un Estado o de una organización de cometer ese ataque o para promover esa política</mark></span>El <span class=\"ref-norma\">art. 7.2.a de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"de conformidad con la política de un Estado o de una organización de cometer ese ataque o para promover esa política\"</span>. Debe responder a la política de un Estado o de una organización. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-168","p":"Estatuto de Roma de la Corte Penal Internacional. Crímenes de lesa humanidad. Definiciones. A los efectos del párrafo 1, por «ataque contra una población civil» se entenderá una línea de conducta que implique la comisión múltiple de actos mencionados en el párrafo 1 contra una población civil, de conformidad con la política de un Estado o de __________ de cometer ese ataque o para promover esa política:","o":["una organización","un grupo armado organizado","una autoridad pública","una organización internacional"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">una organización</mark></span>Según el <span class=\"ref-norma\">art. 7.2.a) del Estatuto de Roma</span>: <span class=\"ref-concepto\">\"de conformidad con la política de un Estado o de una organización de cometer ese ataque o para promover esa política\"</span>. El ataque debe responder a la política de un Estado o de una organización. <i>(marca EXOF / sello «PREGUNTA EXAMEN» del temario)</i><!--t1m:lote1-->"},{"i":"1-ia-3646","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. El «exterminio» comprenderá la imposición intencional de condiciones de vida, entre otras, la privación del acceso a alimentos o medicinas encaminadas a causar:","o":["la destrucción total de una población.","la muerte de los miembros de un grupo.","el debilitamiento físico de una población.","la destrucción de parte de una población."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la destrucción de parte de una población</mark></span>El <span class=\"ref-norma\">art. 7.2.b de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"encaminadas a causar la destrucción de parte de una población\"</span>. La finalidad es la destrucción de parte de una población. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3647","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Por «esclavitud» se entenderá el ejercicio de los atributos del derecho de propiedad sobre una persona, o de algunos de ellos, incluido el ejercicio de esos atributos en:","o":["la explotación laboral de personas, en particular migrantes.","el trabajo forzoso de personas, en particular menores.","el tráfico de personas, en particular mujeres y niños.","la trata de seres humanos con fines de explotación sexual."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el tráfico de personas, en particular mujeres y niños</mark></span>El <span class=\"ref-norma\">art. 7.2.c de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"incluido el ejercicio de esos atributos en el tráfico de personas, en particular mujeres y niños\"</span>. Incluye el tráfico de personas, en particular de mujeres y niños. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3648","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Por «deportación o traslado forzoso de población» se entenderá el desplazamiento forzoso de las personas afectadas, por expulsión u otros actos coactivos, de la zona en que estén legítimamente presentes, sin motivos autorizados por:","o":["el derecho interno del Estado.","el derecho internacional.","el Consejo de Seguridad de las Naciones Unidas.","el derecho internacional humanitario."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el derecho internacional</mark></span>El <span class=\"ref-norma\">art. 7.2.d de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"de la zona en que estén legítimamente presentes, sin motivos autorizados por el derecho internacional\"</span>. Se trata de motivos no autorizados por el derecho internacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3640","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Constituye crimen de lesa humanidad, entre otros actos, la deportación o:","o":["expulsión colectiva de población.","traslado forzoso de población.","desplazamiento forzoso de población.","confinamiento forzoso de población."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">traslado forzoso de población</mark></span>El <span class=\"ref-norma\">art. 7.1.d de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"Deportación o traslado forzoso de población\"</span>. El acto se denomina deportación o traslado forzoso de población. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3649","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Por «tortura» se entenderá causar intencionalmente dolor o sufrimientos graves, ya sean físicos o mentales, a una persona que el acusado tenga bajo su custodia o control; no se entenderá por tortura el dolor o los sufrimientos que se deriven únicamente de:","o":["sanciones lícitas o que sean consecuencia normal o fortuita de ellas.","medidas disciplinarias legalmente impuestas por la autoridad competente.","tratamientos médicos o científicos aplicados con consentimiento del interesado.","actuaciones policiales de coerción proporcionadas a la resistencia ofrecida."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">sanciones lícitas o que sean consecuencia normal o fortuita de ellas</mark></span>El <span class=\"ref-norma\">art. 7.2.e de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"no se entenderá por tortura el dolor o los sufrimientos que se deriven únicamente de sanciones lícitas o\"</span>. La excepción son las sanciones lícitas y sus consecuencias normales o fortuitas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-203","p":"Estatuto de Roma de la Corte Penal Internacional. Crímenes de lesa humanidad. Definiciones (tortura). Por «tortura» se entenderá causar intencionalmente dolor o sufrimientos graves, ya sean físicos o mentales, a una persona que el acusado tenga bajo su __________; sin embargo, no se entenderá por tortura el dolor o los sufrimientos que se deriven únicamente de sanciones lícitas o que sean consecuencia normal o fortuita de ellas.","o":["custodia exclusiva","autoridad o mando","poder o jurisdicción","custodia o control"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">custodia o control</mark></span>Según el <span class=\"ref-norma\">art. 7.2.e) del Estatuto de Roma</span>: <span class=\"ref-concepto\">\"a una persona que el acusado tenga bajo su custodia o control\"</span>. No es tortura el dolor derivado únicamente de sanciones lícitas. <i>(asterisco ✱ del temario)</i><!--t1m:lote2-->"},{"i":"1-ia-3641","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Constituye crimen de lesa humanidad la encarcelación u otra privación grave de la libertad física:","o":["en violación de normas fundamentales de derecho internacional.","en violación de las garantías procesales reconocidas por el Derecho interno.","sin resolución judicial motivada que la autorice.","con una duración superior a la prevista por la ley."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en violación de normas fundamentales de derecho internacional</mark></span>El <span class=\"ref-norma\">art. 7.1.e de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"Encarcelación u otra privación grave de la libertad física en violación de normas fundamentales\"</span>. Debe violar normas fundamentales de derecho internacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3650","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Por «embarazo forzado» se entenderá el confinamiento ilícito de una mujer a la que se ha dejado embarazada por la fuerza, con la intención de modificar la composición étnica de una población o de cometer otras violaciones graves del derecho internacional; en modo alguno se entenderá que esta definición afecta:","o":["a las normas de derecho internacional relativas a la interrupción del embarazo.","a las legislaciones nacionales que regulen el aborto en cada Estado parte.","a los derechos reconocidos a las mujeres embarazadas por los tratados vigentes.","a las normas de derecho interno relativas al embarazo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a las normas de derecho interno relativas al embarazo</mark></span>El <span class=\"ref-norma\">art. 7.2.f de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"En modo alguno se entenderá que esta definición afecta a las normas de derecho interno relativas al embarazo\"</span>. La definición no afecta a las normas internas sobre el embarazo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3701","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Por «persecución» se entenderá la privación intencional y grave de derechos fundamentales en contravención del derecho internacional en razón de:","o":["la identidad del grupo o de la colectividad.","la pertenencia del grupo o de la colectividad a una minoría nacional.","las convicciones políticas o religiosas de los miembros del grupo.","la política de un Estado o de una organización contra el grupo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la identidad del grupo o de la colectividad</mark></span>El <span class=\"ref-norma\">art. 7.2.g de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"en contravención del derecho internacional en razón de la identidad del grupo o de la colectividad\"</span>. La persecución se define por la privación de derechos fundamentales en razón de la identidad del grupo o colectividad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3702","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Por el crimen de «apartheid» se entenderán los actos inhumanos de carácter similar a los mencionados cometidos en el contexto de un régimen institucionalizado de opresión y dominación sistemáticas de un grupo racial sobre uno o más grupos raciales y con:","o":["la intención de destruir a los grupos raciales dominados.","el conocimiento de que forman parte de un ataque generalizado.","la autorización de una autoridad estatal u organización política.","la intención de mantener ese régimen."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la intención de mantener ese régimen</mark></span>El <span class=\"ref-norma\">art. 7.2.h de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"con la intención de mantener ese régimen\"</span>. Se exige la intención de mantener el régimen de opresión y dominación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3703","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. Por «desaparición forzada de personas» se entenderá la aprehensión, la detención o el secuestro de personas por un Estado o una organización política o con su autorización, apoyo o aquiescencia, seguido de la negativa a admitir tal privación de libertad o dar información sobre la suerte o el paradero de esas personas, con la intención de dejarlas fuera del amparo de la ley:","o":["de forma definitiva.","por un período indeterminado.","por un período prolongado.","durante el tiempo que dure la investigación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por un período prolongado</mark></span>El <span class=\"ref-norma\">art. 7.2.i de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"con la intención de dejarlas fuera del amparo de la ley por un período prolongado\"</span>. La intención es dejarlas fuera del amparo de la ley por un período prolongado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-21","p":"Según la Declaración de los Derechos del Hombre y del Ciudadano, la ley no tiene derecho a prohibir más que las acciones nocivas para:","o":["El ciudadano.","El gobierno.","La sociedad.","Las personas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La sociedad.</mark></span><span class=\"ref-norma\">Declaración de los Derechos del Hombre y del Ciudadano de 1789, art. 5</span> dispone: <span class=\"ref-concepto\">\"La Ley no tiene derecho a prohibir más que las acciones nocivas para la sociedad\"</span>. Así se protege el interés colectivo y la libertad."},{"i":"1-ia-3704","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de lesa humanidad. A los efectos del Estatuto, se entenderá que el término «género» se refiere a los dos sexos, masculino y femenino, en el contexto de la sociedad; el término «género»:","o":["incluirá cualquier otra acepción reconocida por el derecho internacional.","no tendrá más acepción que la que antecede.","podrá interpretarse conforme a la jurisprudencia de la Corte.","se aplicará con arreglo al derecho interno de cada Estado parte."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no tendrá más acepción que la que antecede</mark></span>El <span class=\"ref-norma\">art. 7.3 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"El término «género» no tendrá más acepción que\"</span>. La definición es cerrada: dos sexos y ninguna otra acepción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3705","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. La Corte tendrá competencia respecto de los crímenes de guerra, en particular, cuando se cometan:","o":["como parte de un plan o política o como parte de la comisión en gran escala de tales crímenes.","como parte de un ataque generalizado o sistemático contra una población civil.","en el contexto de un conflicto armado internacional y con intención de destruir al enemigo, en los términos que establezca la propia norma.","por orden de un superior jerárquico o de un Gobierno en el ejercicio de sus funciones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">como parte de un plan o política o como parte de la comisión en gran escala de tales crímenes</mark></span>El <span class=\"ref-norma\">art. 8.1 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"en particular, cuando se cometan como parte de un plan o política o como parte de la comisión en gran escala de tales crímenes\"</span>. La competencia sobre crímenes de guerra se centra en plan o política o comisión en gran escala. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3707","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Constituye infracción grave de los Convenios de Ginebra, como crimen de guerra, la destrucción y la apropiación de bienes, no justificadas por necesidades militares, y efectuadas:","o":["de manera sistemática y con ánimo de lucro.","con carácter deliberado y de forma generalizada.","a gran escala, ilícita y arbitrariamente.","a gran escala y con la finalidad de debilitar al enemigo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a gran escala, ilícita y arbitrariamente</mark></span>El <span class=\"ref-norma\">art. 8.2.a de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"no justificadas por necesidades militares, y efectuadas a gran escala, ilícita y arbitrariamente\"</span>. Debe ser a gran escala, ilícita y arbitraria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3706","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Son crímenes de guerra las infracciones graves de los Convenios de Ginebra de 12 de agosto de 1949, a saber, cualquiera de los actos contra personas o bienes protegidos, entre ellos:","o":["el hecho de impedir a un prisionero de guerra la comunicación con su familia o con la Potencia protectora, salvo que se disponga otra cosa en la normativa aplicable.","el hecho de someter a un prisionero de guerra a trabajos penosos no justificados por la disciplina.","el hecho de trasladar a prisioneros de guerra a zonas de combate sin protección suficiente.","el hecho de forzar a un prisionero de guerra o a otras personas protegidas a servir en las fuerzas de una Potencia enemiga."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el hecho de forzar a un prisionero de guerra o a otras personas protegidas a servir en las fuerzas de una Potencia enemiga</mark></span>El <span class=\"ref-norma\">art. 8.2.a de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"El hecho de forzar a un prisionero de guerra o a otras personas protegidas a servir en las fuerzas\"</span>. Forzar a servir en las fuerzas de una Potencia enemiga es una infracción grave listada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3708","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Entre las infracciones graves de los Convenios de Ginebra, como crímenes de guerra, figuran el homicidio intencional, la tortura o los tratos inhumanos, incluidos los experimentos biológicos, la deportación o el traslado ilegal o el confinamiento ilegal y:","o":["el reclutamiento de menores de quince años.","la toma de rehenes.","el empleo de veneno o armas envenenadas.","el saqueo de una ciudad o plaza."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la toma de rehenes</mark></span>El <span class=\"ref-norma\">art. 8.2.a de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"La deportación o el traslado ilegal, o el confinamiento ilegal; viii) La toma de rehenes\"</span>. La toma de rehenes figura entre las infracciones graves (apartado a); las demás son otras violaciones graves de las leyes y usos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-204","p":"Estatuto de Roma de la Corte Penal Internacional. Crímenes de guerra. A los efectos del presente Estatuto, se entiende por «crímenes de guerra»: b) Otras violaciones graves de las leyes y usos aplicables en los __________ dentro del marco establecido de derecho internacional, a saber, cualquiera de los actos siguientes:","o":["conflictos armados que no son de índole internacional","conflictos armados, internos o internacionales","conflictos armados internacionales","territorios ocupados y conflictos armados internacionales"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">conflictos armados internacionales</mark></span>Según el <span class=\"ref-norma\">art. 8.2.b) del Estatuto de Roma</span>: <span class=\"ref-concepto\">\"Otras violaciones graves de las leyes y usos aplicables en los conflictos armados internacionales dentro del marco establecido de derecho internacional\"</span>. El apartado b) se refiere a los conflictos armados internacionales; el e), a los que no son de índole internacional. <i>(asterisco ✱ del temario)</i><!--t1m:lote2-->"},{"i":"1-ia-3709","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. En los conflictos armados internacionales, constituye otra violación grave de las leyes y usos aplicables dirigir intencionalmente ataques contra la población civil en cuanto tal o contra personas civiles que no participen directamente en las hostilidades y también contra:","o":["bienes civiles, es decir, bienes que no son objetivos militares.","bienes culturales, aunque sean utilizados con fines militares por el enemigo.","bienes de la Potencia ocupante, aunque no tengan carácter militar.","bienes públicos del Estado enemigo, por su valor estratégico."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">bienes civiles, es decir, bienes que no son objetivos militares</mark></span>El <span class=\"ref-norma\">art. 8.2.b.i y ii de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"Dirigir intencionalmente ataques contra bienes civiles, es decir, bienes que no son objetivos\"</span>. Se incluyen los bienes civiles, entendidos como los que no son objetivos militares. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3710","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Constituye crimen de guerra lanzar un ataque intencionalmente, a sabiendas de que causará pérdidas incidentales de vidas, lesiones a civiles o daños a bienes de carácter civil o daños extensos, duraderos y graves al medio ambiente natural que serían:","o":["desproporcionados en relación con la ventaja militar que se obtenga con el ataque.","manifiestamente excesivos en relación con la ventaja estratégica global que se pretenda alcanzar.","manifiestamente injustificados en relación con la ventaja militar concreta y directa que se prevea, salvo que se disponga otra cosa en la normativa aplicable.","manifiestamente excesivos en relación con la ventaja militar concreta y directa de conjunto que se prevea."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">manifiestamente excesivos en relación con la ventaja militar concreta y directa de conjunto que se prevea</mark></span>El <span class=\"ref-norma\">art. 8.2.b.iv de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"que serían manifiestamente excesivos en relación con la ventaja militar concreta\"</span>. Debe ser manifiestamente excesivo en relación con la ventaja militar concreta y directa de conjunto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3711","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Constituye crimen de guerra atacar o bombardear, por cualquier medio, ciudades, aldeas, viviendas o edificios que:","o":["no estén defendidos y que no hayan sido declarados zona neutral.","no estén ocupados por combatientes y no sean objetivos militares.","no estén defendidos y que no sean objetivos militares.","no sean objetivos militares y estén habitados por población civil."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no estén defendidos y que no sean objetivos militares</mark></span>El <span class=\"ref-norma\">art. 8.2.b.v de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"ciudades, aldeas, viviendas o edificios que no estén defendidos y que no sean objetivos militares\"</span>. Se exige que no estén defendidos y que no sean objetivos militares. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3712","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Constituye crimen de guerra causar la muerte o lesiones a un combatiente que haya depuesto las armas o que, al no tener medios para defenderse, se haya:","o":["rendido incondicionalmente.","rendido a discreción.","entregado a las fuerzas enemigas.","puesto bajo protección de la Cruz Roja."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">rendido a discreción</mark></span>El <span class=\"ref-norma\">art. 8.2.b.vi de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"se haya rendido a discreción\"</span>. La fórmula es «rendido a discreción». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3714","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Constituye crimen de guerra dirigir intencionalmente ataques contra edificios dedicados a la religión, la educación, las artes, las ciencias o la beneficencia, los monumentos históricos, los hospitales y los lugares en que se agrupa a enfermos y heridos, siempre que:","o":["no estén señalizados con los emblemas distintivos.","no estén defendidos por fuerzas militares.","no hayan sido declarados patrimonio de la humanidad.","no sean objetivos militares."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no sean objetivos militares</mark></span>El <span class=\"ref-norma\">art. 8.2.b.ix de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"siempre que no sean objetivos militares\"</span>. Quedan protegidos siempre que no sean objetivos militares. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3715","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Constituye crimen de guerra matar o herir a traición a personas pertenecientes a la nación o al ejército enemigo y también:","o":["obligar a combatientes enemigos a prestar servicio de guías.","ocultar la identidad de las unidades que participan en las hostilidades.","declarar que no se dará cuartel.","emplear combatientes que no lleven distintivo alguno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">declarar que no se dará cuartel</mark></span>El <span class=\"ref-norma\">art. 8.2.b.xi y xii de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"Matar o herir a traición a personas pertenecientes a la nación o al ejército enemigo; xii) Declarar que no se dará cuartel\"</span>. Declarar que no se dará cuartel es crimen de guerra. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3716","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Constituye crimen de guerra obligar a los nacionales de la parte enemiga a participar en operaciones bélicas dirigidas contra su propio país, aunque hubieran estado:","o":["bajo la jurisdicción del beligerante antes del inicio de la guerra.","al servicio del beligerante antes del inicio de la guerra.","en el territorio del beligerante antes del inicio de la guerra.","sometidos al régimen de ocupación antes del inicio de la guerra."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al servicio del beligerante antes del inicio de la guerra</mark></span>El <span class=\"ref-norma\">art. 8.2.b.xv de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"aunque hubieran estado al servicio del beligerante antes del inicio de la guerra\"</span>. Aunque hubieran estado al servicio del beligerante antes de la guerra. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3717","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Constituye crimen de guerra emplear veneno o armas envenenadas, gases asfixiantes, tóxicos o similares y balas que se ensanchan o aplastan fácilmente en el cuerpo humano, como:","o":["balas de camisa dura que no recubra totalmente la parte interior o que tenga incisiones.","balas incendiarias que provoquen quemaduras graves en el cuerpo humano, en los términos que establezca la propia norma.","balas explosivas que se fragmenten al impactar con el objetivo.","balas perforantes que atraviesen los chalecos de protección individual."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">balas de camisa dura que no recubra totalmente la parte interior o que tenga incisiones</mark></span>El <span class=\"ref-norma\">art. 8.2.b.xvii a xx de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"como balas de\"</span>. La descripción es la de balas de camisa dura que no recubra totalmente la parte interior o que tenga incisiones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3718","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Constituye crimen de guerra emplear armas, proyectiles, materiales y métodos de guerra que causen daños superfluos o sufrimientos innecesarios o surtan efectos indiscriminados, a condición de que sean objeto de una prohibición completa y estén:","o":["enumerados en un tratado internacional de desarme ratificado por la Corte.","incluidos en una lista aprobada por la Asamblea de los Estados Partes.","declarados ilícitos por el Consejo de Seguridad de las Naciones Unidas.","incluidos en un anexo del Estatuto en virtud de una enmienda aprobada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">incluidos en un anexo del Estatuto en virtud de una enmienda aprobada</mark></span>El <span class=\"ref-norma\">art. 8.2.b.xx de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"sean objeto de una prohibición completa y estén\"</span>. Solo si están incluidos en un anexo del Estatuto en virtud de una enmienda aprobada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3719","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Constituye crimen de guerra cometer atentados contra la dignidad personal; especialmente los tratos humillantes y degradantes, y cometer actos de violación, esclavitud sexual, prostitución forzada, embarazo forzado, esterilización forzada y cualquier otra forma de violencia sexual que:","o":["sea de gravedad comparable a las anteriores.","se cometa como parte de un plan o política.","también constituya una infracción grave de los Convenios de Ginebra.","atente gravemente contra la integridad física o mental, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">también constituya una infracción grave de los Convenios de Ginebra</mark></span>El <span class=\"ref-norma\">art. 8.2.b.xxi y xxii de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"cualquier otra forma de vio-lencia sexual que también constituya una infracción grave de los Convenios de Ginebra\"</span>. En el marco de guerra se exige que constituya también una infracción grave de los Convenios de Ginebra. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-149","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra (EX). Constituye una violación grave de las leyes y usos aplicables en los conflictos armados internacionales reclutar o alistar a niños menores de:","o":["quince años en las fuerzas armadas nacionales o utilizarlos para participar activamente en las hostilidades.","dieciséis años en las fuerzas armadas nacionales o utilizarlos para participar activamente en las hostilidades.","dieciocho años en las fuerzas armadas nacionales o utilizarlos para participar activamente en las hostilidades.","quince años en grupos armados irregulares, pero no en las fuerzas armadas nacionales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">quince años en las fuerzas armadas nacionales o utilizarlos para participar activamente en las hostilidades</mark></span>El <span class=\"ref-norma\">art. 8.2.b.xxvi) de el Estatuto de Roma de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"xxvi) Reclutar o alistar a niños menores de quince años en las fuerzas armadas nacionales o utilizarlos para participar activamente en las hostilidades\"</span>. El umbral es el de quince años."},{"i":"1-ia-3720","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Constituye crimen de guerra hacer padecer intencionalmente hambre a la población civil como método de hacer la guerra y reclutar o alistar a niños menores de:","o":["dieciocho años en las fuerzas armadas nacionales o utilizarlos para participar activamente en las hostilidades.","quince años en las fuerzas armadas nacionales o utilizarlos para participar activamente en las hostilidades.","dieciséis años en las fuerzas armadas nacionales o utilizarlos para participar activamente en las hostilidades.","quince años en las fuerzas armadas o en grupos armados organizados que no sean nacionales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">quince años en las fuerzas armadas nacionales o utilizarlos para participar activamente en las hostilidades</mark></span>El <span class=\"ref-norma\">art. 8.2.b.xxv y xxvi de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"Reclutar o alistar a niños menores de quince años en las fuerzas armadas nacionales o utilizarlos\"</span>. La edad es quince años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3721","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Constituye crimen de guerra emplear armas que utilicen agentes microbianos u otros agentes biológicos, o toxinas, cualquier arma cuyo efecto principal sea lesionar mediante fragmentos que no puedan localizarse por rayos X y armas láser específicamente concebidas para causar:","o":["ceguera permanente a la vista no amplificada.","lesiones permanentes en los órganos de la visión y audición.","ceguera temporal o permanente en los combatientes enemigos.","daños oculares irreversibles en la población civil."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">ceguera permanente a la vista no amplificada</mark></span>El <span class=\"ref-norma\">art. 8.2.b.xxvii a xxix de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"para causar ceguera permanente a la vista no amplificada, es decir, al ojo descubierto\"</span>. Las armas láser prohibidas son las concebidas para causar ceguera permanente a la vista no amplificada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3722","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. En caso de conflicto armado que no sea de índole internacional, son crímenes de guerra las violaciones graves del precepto común a los cuatro Convenios de Ginebra para los conflictos no internacionales, cometidas contra personas que no participen directamente en las hostilidades, incluidos los miembros de las Fuerzas Armadas que:","o":["hayan sido hechos prisioneros y las personas puestas fuera de combate por enfermedad, herida o detención, salvo que se disponga otra cosa en la normativa aplicable.","se hayan rendido incondicionalmente y las personas que presten servicios sanitarios o religiosos.","hayan abandonado sus unidades y las personas retenidas por una parte en el conflicto.","hayan depuesto las armas y las personas puestas fuera de combate por enfermedad, herida, detención o por cualquier otra causa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">hayan depuesto las armas y las personas puestas fuera de combate por enfermedad, herida, detención o por cualquier otra causa</mark></span>El <span class=\"ref-norma\">art. 8.2.c de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"incluidos los miembros de las Fuerzas Armadas que hayan depuesto las armas y las personas puestas\"</span>. Se protege a quienes han depuesto las armas y a los puestos fuera de combate por cualquier causa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3723","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. En conflicto armado no internacional, constituyen crímenes de guerra las condenas dictadas y las ejecuciones sin previo juicio ante un tribunal regularmente constituido, con:","o":["todas las garantías procesales previstas por el derecho interno del Estado.","las garantías mínimas del debido proceso reconocidas en los Convenios de Ginebra.","todas las garantías judiciales generalmente reconocidas como indispensables.","las garantías de independencia e imparcialidad propias de los tribunales ordinarios."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">todas las garantías judiciales generalmente reconocidas como indispensables</mark></span>El <span class=\"ref-norma\">art. 8.2.c.iv de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"con todas las garantías judiciales generalmente reconocidas como indispensables\"</span>. Se exige un tribunal regularmente constituido y todas las garantías judiciales generalmente reconocidas como indispensables. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3724","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Las violaciones graves del precepto común a los Convenios de Ginebra se aplican a los conflictos armados que no son de índole internacional y, por consiguiente, no se aplican a las situaciones de:","o":["ocupación militar y de ejercicio de la autoridad de hecho sobre un territorio extranjero.","tensiones internas y de disturbios interiores, tales como los motines, los actos esporádicos y aislados de violencia u otros actos análogos.","conflictos armados prolongados entre las autoridades gubernamentales y grupos armados organizados, sin perjuicio de lo dispuesto en otras disposiciones.","operaciones de mantenimiento de la paz autorizadas por el Consejo de Seguridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tensiones internas y de disturbios interiores, tales como los motines, los actos esporádicos y aislados de violencia u otros actos análogos</mark></span>El <span class=\"ref-norma\">art. 8.2.d de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"por consiguiente, no se aplica a las situaciones de tensiones internas y de disturbios inte-riores, tales como los motines, los actos esporádicos y aislados de violencia u otros actos análogos\"</span>. Quedan fuera las tensiones internas y los disturbios interiores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3725","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. En conflictos armados que no sean de índole internacional, constituye otra violación grave de las leyes y usos aplicables ordenar el desplazamiento de la población civil por razones relacionadas con el conflicto, a menos que:","o":["así lo exija la seguridad de los civiles de que se trate o por razones militares imperativas.","lo ordene la autoridad competente con arreglo al derecho interno del Estado.","se trate de un desplazamiento temporal y con garantías de retorno a las zonas de origen.","lo autorice el Consejo de Seguridad en el ejercicio de sus funciones de mantenimiento de la paz."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">así lo exija la seguridad de los civiles de que se trate o por razones militares imperativas</mark></span>El <span class=\"ref-norma\">art. 8.2.e de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"a me-nos que así lo exija la seguridad de los civiles de que se trate o por razones militares imperativas\"</span>. Solo si lo exige la seguridad de los civiles o razones militares imperativas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3726","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Los crímenes de guerra en conflictos armados que no son de índole internacional se aplican a los conflictos que tienen lugar en el territorio de un Estado cuando existe:","o":["un conflicto armado de especial intensidad entre las fuerzas armadas del Estado y grupos insurgentes, salvo que se disponga otra cosa en la normativa aplicable.","una situación de violencia armada generalizada que ponga en peligro la existencia del Estado.","un conflicto armado entre grupos organizados con control territorial y mando responsable.","un conflicto armado prolongado entre las autoridades gubernamentales y grupos armados organizados o entre tales grupos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un conflicto armado prolongado entre las autoridades gubernamentales y grupos armados organizados o entre tales grupos</mark></span>El <span class=\"ref-norma\">art. 8.2.f de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"cuando existe un conflicto armado prolongado entre las autoridades gubernamentales y grupos armados organizados o entre tales grupos\"</span>. El umbral es un conflicto armado prolongado entre autoridades y grupos armados organizados, o entre estos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3727","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Crímenes de guerra. Nada de lo dispuesto sobre los conflictos armados no internacionales afectará a la responsabilidad que incumbe a todo gobierno de mantener o restablecer el orden público en el Estado o de defender la unidad e integridad territorial del Estado:","o":["por cualquier medio proporcionado.","por los medios previstos en su ordenamiento.","por cualquier medio legítimo.","por todos los medios necesarios."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por cualquier medio legítimo</mark></span>El <span class=\"ref-norma\">art. 8.3 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"defender la unidad e integridad territorial del Estado por cualquier medio legítimo\"</span>. El Estatuto habla de «cualquier medio legítimo». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 19.6 · IMPUGNACIÓN DE LA ADMISIBILIDAD DE UNA CAUSA O DE LA COMPETENCIA DE LA CORTE","q":[{"i":"1-82","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Impugnación de la competencia de la Corte o de la admisibilidad de la causa. Las decisiones relativas a la competencia o la admisibilidad, podrán ser recurridas ante:","o":["A la Sala de Cuestiones Preliminares.","La Sala de Primera Instancia.","La Gran Sala.","La Sala de Apelaciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Sala de Apelaciones</mark></span>Según el <span class=\"ref-norma\">art. 19.6 del Estatuto de Roma de la Corte Penal Internacional</span>: <span class=\"ref-concepto\">\"Las decisiones relativas a la competencia o la admisibilidad podrán ser recurridas ante la Sala de Apelaciones de conformidad con el artículo 82.\"</span> (verificado con el texto del temario)."},{"i":"1-211","p":"Estatuto de Roma de la Corte Penal Internacional. Impugnación de la competencia de la Corte o de la admisibilidad de la causa. Podrán impugnar la admisibilidad de la causa, por uno de los motivos mencionados en el artículo 17, o impugnar la competencia de la Corte:","o":["El acusado, el Estado de su nacionalidad en todo caso y las víctimas de los crímenes.","Únicamente el acusado y la persona contra la cual se haya dictado una orden de detención.","El acusado, cualquier Estado Parte y el Consejo de Seguridad de las Naciones Unidas.","El acusado, un Estado que tenga jurisdicción en la causa porque está investigándola o enjuiciándola o lo ha hecho antes, y un Estado cuya aceptación se requiera de conformidad con el artículo 12."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El acusado, un Estado que tenga jurisdicción en la causa porque está investigándola o enjuiciándola o lo ha hecho antes, y un Estado cuya aceptación se requiera de conformidad con el artículo 12</mark></span>Según el <span class=\"ref-norma\">art. 19.2 del Estatuto de Roma</span>: <span class=\"ref-concepto\">\"Podrán impugnar la admisibilidad de la causa, por uno de los motivos mencionados en el artículo 17, o impugnar la competencia de la Corte\"</span>. Legitimados: el acusado (o la persona con orden de detención), el Estado con jurisdicción y el Estado cuya aceptación se requiera (art. 12). <i>(asterisco ✱ del temario)</i><!--t1m:lote2-->"},{"i":"1-ia-3061","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De las actuaciones posteriores a la entrega. Cuando la persona entregada fuere puesta en libertad por la Corte por razones distintas del cumplimiento de la sentencia y la Corte se propusiera trasladarla a otro Estado, el Ministerio de Justicia dará el consentimiento de España o solicitará su devolución a España si la razón de la puesta en libertad se debiere a que:","o":["la causa fue declarada inadmisible por la Corte por el motivo previsto en el Estatuto.","la acusación fue retirada por el Fiscal de la Corte.","la persona entregada fue absuelta por falta de pruebas, en los términos que establezca la propia norma.","la Corte declaró prescritos los hechos imputados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la causa fue declarada inadmisible por la Corte por el motivo previsto en el Estatuto</mark></span>El <span class=\"ref-norma\">art. 19.2 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"si la razón de la puesta en libertad se debiere a que la causa fue declarada inadmisible por la Corte por el motivo previsto en el artículo 17.1.a) del Estatuto\"</span>. Se solicita la devolución cuando la causa fue declarada inadmisible por la Corte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3808","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Impugnación de la competencia de la Corte o de la admisibilidad de la causa. La Corte se cerciorará de ser competente en todas las causas que le sean sometidas y, además, podrá determinar:","o":["a petición del fiscal la admisibilidad de una causa.","de oficio la admisibilidad de una causa.","previo informe de la Asamblea de los Estados Partes la admisibilidad de una causa.","a instancia de las víctimas la admisibilidad de una causa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de oficio la admisibilidad de una causa</mark></span>El <span class=\"ref-norma\">art. 19.1 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"La Corte podrá determinar de oficio la admisibilidad de una causa\"</span>. La Corte puede apreciar de oficio la admisibilidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3809","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Impugnación de la competencia de la Corte o de la admisibilidad de la causa. Podrán impugnar la admisibilidad de la causa o impugnar la competencia de la Corte el acusado o la persona contra la cual se haya dictado una orden de detención o de comparecencia, un Estado que tenga jurisdicción en la causa y:","o":["un Estado cuya aceptación se requiera de conformidad con las condiciones previas para el ejercicio de la competencia.","el Estado en cuyo territorio se hayan cometido los crímenes, aunque no tenga jurisdicción sobre la causa, en los términos que establezca la propia norma.","las víctimas que hayan presentado observaciones ante la Sala de Cuestiones Preliminares.","el Consejo de Seguridad cuando haya remitido la situación a la Corte con arreglo al Capítulo VII."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">un Estado cuya aceptación se requiera de conformidad con las condiciones previas para el ejercicio de la competencia</mark></span>El <span class=\"ref-norma\">art. 19.2 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"Un Estado cuya aceptación se requiera de conformidad con el artículo 12\"</span>. Pueden impugnar el acusado, el Estado con jurisdicción y el Estado cuya aceptación se requiera. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3810","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Impugnación de la competencia de la Corte o de la admisibilidad de la causa. El fiscal podrá pedir a la Corte que se pronuncie sobre una cuestión de competencia o de admisibilidad; en las actuaciones relativas a la competencia o la admisibilidad, podrán presentar asimismo observaciones a la Corte:","o":["los Estados Partes y las organizaciones intergubernamentales.","el acusado y los Estados que hayan cooperado con la Corte.","las víctimas y la Asamblea de los Estados Partes.","quienes hayan remitido la situación y las víctimas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">quienes hayan remitido la situación y las víctimas</mark></span>El <span class=\"ref-norma\">art. 19.3 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"podrán presentar asimismo observa-ciones a la Corte quienes hayan remitido la situación de conformidad con el artículo 13 y las víctimas\"</span>. Presentan observaciones quienes remitieron la situación y las víctimas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3811","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Impugnación de la competencia de la Corte o de la admisibilidad de la causa. La admisibilidad de una causa o la competencia de la Corte sólo podrán ser impugnadas una sola vez; la impugnación se hará antes del juicio o a su inicio y, en circunstancias excepcionales, la Corte podrá autorizar que:","o":["la impugnación se haga en cualquier momento mediante recurso ante la Sala de Apelaciones.","la impugnación se haga sin límite temporal cuando existan hechos nuevos de especial gravedad.","la impugnación se haga más de una vez o en una fase ulterior del juicio.","la impugnación se haga hasta que se dicte sentencia por la Sala de Primera Instancia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la impugnación se haga más de una vez o en una fase ulterior del juicio</mark></span>El <span class=\"ref-norma\">art. 19.4 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"En circunstancias excepcionales, la Corte podrá autorizar que la im-pugnación se haga más de una vez o en una fase ulterior del juicio\"</span>. Excepcionalmente se autoriza más de una impugnación o en fase ulterior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3812","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Impugnación de la competencia de la Corte o de la admisibilidad de la causa. Antes de la confirmación de los cargos, la impugnación de la admisibilidad de una causa o de la competencia de la Corte será asignada a:","o":["la Sala de Primera Instancia, sin perjuicio de lo dispuesto en otras disposiciones.","la Sala de Cuestiones Preliminares.","la Sala de Apelaciones.","la Presidencia de la Corte."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la Sala de Cuestiones Preliminares</mark></span>El <span class=\"ref-norma\">art. 19.6 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"la impugnación de la admisibilidad de una causa o de la competencia de la Corte será asignada a la Sala de Cuestiones Preliminares\"</span>. Antes de la confirmación de cargos, a la Sala de Cuestiones Preliminares; después, a la Sala de Primera Instancia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3813","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Impugnación de la competencia de la Corte o de la admisibilidad de la causa. Después de confirmados los cargos, la impugnación de la admisibilidad de una causa o de la competencia de la Corte será asignada a la Sala de Primera Instancia y las decisiones podrán ser recurridas ante:","o":["la Sala de Apelaciones.","la Sala de Cuestiones Preliminares.","la Presidencia de la Corte.","la Asamblea de los Estados Partes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Sala de Apelaciones</mark></span>El <span class=\"ref-norma\">art. 19.6 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"será asignada a la Sala de Primera Instancia\"</span>. Las decisiones sobre competencia o admisibilidad se recurren ante la Sala de Apelaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3814","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Impugnación de la competencia de la Corte o de la admisibilidad de la causa. Si la impugnación es hecha por un Estado que tenga jurisdicción en la causa o cuya aceptación se requiera, el fiscal:","o":["continuará la investigación, sin practicar actuaciones que afecten al Estado impugnante.","remitirá las actuaciones a la Sala de Cuestiones Preliminares para su archivo provisional.","solicitará a la Sala de Apelaciones que declare la inadmisibilidad de la impugnación.","suspenderá la investigación hasta que la Corte resuelva sobre la admisibilidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">suspenderá la investigación hasta que la Corte resuelva sobre la admisibilidad</mark></span>El <span class=\"ref-norma\">art. 19.7 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"el fiscal suspenderá la investigación hasta que la Corte resuelva de conformidad con el artículo 17\"</span>. La impugnación estatal suspende la investigación hasta la resolución de la Corte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3815","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Impugnación de la competencia de la Corte o de la admisibilidad de la causa. Hasta antes de que la Corte se pronuncie sobre la impugnación, el fiscal podrá pedirle autorización para practicar las indagaciones necesarias, tomar declaración a un testigo o completar la recolección de pruebas que hubiere iniciado y:","o":["solicitar la detención provisional de las personas investigadas ante las autoridades del Estado donde se encuentren, conforme al procedimiento que se establezca reglamentariamente.","proceder a la entrega de las personas respecto de las cuales haya pedido ya una orden de comparecencia.","impedir, en cooperación con los Estados que corresponda, que eludan la acción de la justicia personas respecto de las cuales el fiscal haya pedido ya una orden de detención.","interrogar a las personas imputadas en presencia de su abogado en la sede de la Corte."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">impedir, en cooperación con los Estados que corresponda, que eludan la acción de la justicia personas respecto de las cuales el fiscal haya pedido ya una orden de detención</mark></span>El <span class=\"ref-norma\">art. 19.8 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"Impedir, en cooperación con los Estados que corresponda, que eludan la acción de la justicia\"</span>. La tercera facultad es impedir la fuga de personas respecto de las cuales ya se pidió orden de detención. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3816","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Impugnación de la competencia de la Corte o de la admisibilidad de la causa. La impugnación de la competencia de la Corte o de la admisibilidad de una causa no afectará:","o":["a la validez de los actos de investigación realizados por el fiscal, aunque sí a las órdenes dictadas por la Corte, sin perjuicio de lo dispuesto en otras disposiciones.","a la validez de ningún acto realizado por el fiscal, ni de ninguna orden o mandamiento dictado por la Corte, antes de ella.","a la validez de las órdenes de la Corte, aunque sí a los actos realizados por el fiscal antes de ella.","a la competencia de la Corte para continuar el procedimiento respecto de otras personas imputadas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a la validez de ningún acto realizado por el fiscal, ni de ninguna orden o mandamiento dictado por la Corte, antes de ella</mark></span>El <span class=\"ref-norma\">art. 19.9 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"La impugnación no afectará a la validez de ningún acto realizado por el fiscal, ni de ninguna orden o\"</span>. No afecta a la validez de actos del fiscal ni de órdenes de la Corte anteriores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3817","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Impugnación de la competencia de la Corte o de la admisibilidad de la causa. Si la Corte hubiere declarado inadmisible una causa, el fiscal podrá pedir que se revise esa decisión cuando se haya cerciorado cabalmente de que:","o":["han aparecido nuevos hechos que invalidan los motivos por los cuales la causa había sido considerada inadmisible.","el Estado que investigaba el asunto ha dejado de estar en condiciones de llevar a cabo el enjuiciamiento, en los términos que establezca la propia norma.","las víctimas han presentado observaciones que cuestionan la imparcialidad del proceso nacional.","ha transcurrido un plazo de seis meses desde la declaración de inadmisibilidad de la causa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">han aparecido nuevos hechos que invalidan los motivos por los cuales la causa había sido considerada inadmisible</mark></span>El <span class=\"ref-norma\">art. 19.10 y 11 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"han aparecido nuevos hechos que invalidan los motivos por los cuales la causa había sido considerada inadmisible\"</span>. La revisión exige que hayan aparecido nuevos hechos que invaliden los motivos de inadmisibilidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-4119","p":"Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional. Testigos. Se reconocerán a los testigos, en la medida en que sea necesario para su comparecencia ante la Corte con el fin de prestar declaración, los privilegios, inmunidades y facilidades, incluso durante el tiempo empleado en viajes, siempre que exhiban:","o":["el certificado firmado por el Secretario de la Corte, igual que los abogados.","la citación judicial notificada personalmente por la autoridad competente.","el documento a que se hace referencia en el propio artículo, extendido por la Corte.","el pasaporte con el visado expedido por el Estado Parte donde se halle la Corte, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el documento a que se hace referencia en el propio artículo, extendido por la Corte</mark></span>El <span class=\"ref-norma\">art. 19.1 de el Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"siempre que exhiban el documento a que se hace referencia en el párrafo 2 del presente artículo\"</span>. Hace falta el documento de la Corte que certifique que deben comparecer y el período necesario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-4120","p":"Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional. Testigos. Los testigos gozarán de inmunidad de jurisdicción de toda índole respecto de las declaraciones que hagan y los actos que realicen en el curso de su testimonio, la cual:","o":["cesará en el momento en que concluya su comparecencia ante la Corte.","subsistirá incluso después de que hayan comparecido y prestado testimonio ante la Corte.","subsistirá durante un año tras haber prestado testimonio ante la Corte, sin perjuicio de lo dispuesto en otras disposiciones.","subsistirá solo respecto de las declaraciones realizadas por escrito."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">subsistirá incluso después de que hayan comparecido y prestado testimonio ante la Corte</mark></span>El <span class=\"ref-norma\">art. 19.1.c de el Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"la cual subsistirá incluso después de que hayan comparecido y prestado testimonio ante la Corte\"</span>. Subsiste después de testificar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-4121","p":"Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional. Testigos. A los efectos de sus comunicaciones con la Corte y sus abogados en relación con su testimonio, los testigos tendrán derecho a:","o":["recibir y enviar papeles y documentos, cualquiera que sea su forma.","utilizar claves o cifras y la valija sellada para su correspondencia.","comunicarse libremente con la Corte sin control de las autoridades del Estado.","recibir y enviar comunicaciones electrónicas sin censura de las autoridades."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">recibir y enviar papeles y documentos, cualquiera que sea su forma</mark></span>El <span class=\"ref-norma\">art. 19.1.e de el Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"el derecho a recibir y enviar papeles y documentos, cualquiera que sea su forma\"</span>. Pueden recibir y enviar papeles y documentos; la valija sellada es para peritos y otras categorías. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-4407","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Impugnación de la competencia o de la admisibilidad. Si la impugnación de la admisibilidad o de la competencia la hace el Estado que investiga o enjuicia el asunto, o aquel cuya aceptación se requiere, el fiscal:","o":["continuará la investigación hasta que la Sala lo ordene, conforme al procedimiento que se establezca reglamentariamente.","archivará el asunto de forma provisional.","suspenderá la investigación hasta que la Corte resuelva.","pedirá al Consejo de Seguridad que decida."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">suspenderá la investigación hasta que la Corte resuelva</mark></span>El <span class=\"ref-norma\">art. 19.7 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"el fiscal suspenderá la investigación hasta que la Corte resuelva de conformidad con el artículo 17\"</span>. La impugnación del Estado obliga al fiscal a suspender la investigación hasta que resuelva la Corte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 58 y 59 — Orden de detención o de comparecencia y procedimiento en el Estado de detención ✱ R26","q":[{"i":"1-169","p":"Estatuto de Roma de la Corte Penal Internacional. Orden de detención o de comparecencia. En cualquier momento después de iniciada la __________, la Sala de Cuestiones Preliminares dictará, a solicitud del fiscal, una orden de detención contra una persona si, tras examinar la solicitud y las pruebas y otra información presentadas por el fiscal, estuviere convencida de que:","o":["confirmación de los cargos","admisión de la causa","primera comparecencia","investigación"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">investigación</mark></span>Según el <span class=\"ref-norma\">art. 58.1 del Estatuto de Roma</span>: <span class=\"ref-concepto\">\"En cualquier momento después de iniciada la investigación, la Sala de Cuestiones Preliminares dictará, a solicitud del fiscal, una orden de detención\"</span>. La orden de detención la dicta la Sala de Cuestiones Preliminares a solicitud del fiscal, ya iniciada la investigación. <i>(marca EXOF / sello «PREGUNTA EXAMEN» del temario)</i><!--t1m:lote1-->"},{"i":"1-153","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Orden de detención (EXAMEN 2020). La Sala de Cuestiones Preliminares dictará, a solicitud del fiscal, una orden de detención contra una persona si estuviere convencida de que hay motivo razonable para creer que ha cometido un crimen de la competencia de la Corte, y de que la detención parece necesaria para:","o":["asegurar que la persona comparezca en juicio, asegurar que no obstruya la investigación o impedir que siga cometiendo ese crimen o un crimen conexo.","asegurar que la persona comparezca en juicio, garantizar el pago de las costas o impedir que siga cometiendo ese crimen.","asegurar que la persona comparezca en juicio o asegurar la ejecución de la pena que pudiera imponerse.","impedir que la persona abandone el territorio del Estado y asegurar que no obstruya la investigación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">asegurar que la persona comparezca en juicio, asegurar que no obstruya la investigación o impedir que siga cometiendo ese crimen o un crimen conexo</mark></span>El <span class=\"ref-norma\">art. 58.1 de el Estatuto de Roma de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"Asegurar que la persona comparezca en juicio; [...] Asegurar que la persona no obstruya ni ponga en peligro la investigación ni las actuaciones de la Corte, o [...] impedir que la persona siga cometiendo ese crimen o un crimen conexo que sea de la competencia de la Corte y tenga su origen en las mismas circunstancias\"</span>. Los tres fines son comparecencia, no obstrucción y evitar la reiteración."},{"i":"1-ia-3843","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Orden de detención u orden de comparecencia dictada por la Sala de Cuestiones Preliminares. En cualquier momento después de iniciada la investigación, la Sala de Cuestiones Preliminares dictará, a solicitud del fiscal, una orden de detención contra una persona si estuviere convencida de que hay motivo razonable para creer que ha cometido un crimen de la competencia de la Corte y de que la detención parece necesaria para asegurar que la persona comparezca en juicio, asegurar que no obstruya ni ponga en peligro la investigación o, en su caso:","o":["impedir que la persona se sustraiga a la acción de la justicia o a la ejecución de la pena, conforme al procedimiento que se establezca reglamentariamente.","garantizar la protección de las víctimas y testigos frente a posibles represalias.","impedir que la persona siga cometiendo ese crimen o un crimen conexo que sea de la competencia de la Corte y tenga su origen en las mismas circunstancias.","asegurar el cumplimiento de la orden de comparecencia dictada previamente por la Sala."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">impedir que la persona siga cometiendo ese crimen o un crimen conexo que sea de la competencia de la Corte y tenga su origen en las mismas circunstancias</mark></span>El <span class=\"ref-norma\">art. 58.1 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"En su caso, impedir que la persona siga cometiendo ese crimen o un crimen conexo que sea de\"</span>. Los tres fines son comparecencia, no obstrucción y evitar la reiteración del crimen o crímenes conexos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3844","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Orden de detención u orden de comparecencia dictada por la Sala de Cuestiones Preliminares. La solicitud de orden de detención del fiscal consignará el nombre de la persona y cualquier otro dato que sirva para su identificación, una referencia expresa al crimen, una descripción concisa de los hechos, un resumen de las pruebas y:","o":["la calificación jurídica y la pena solicitada para la persona.","la razón por la cual el fiscal crea necesaria la detención.","la declaración de las víctimas que hayan presentado observaciones.","la valoración de la gravedad del crimen y de la situación personal del acusado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la razón por la cual el fiscal crea necesaria la detención</mark></span>El <span class=\"ref-norma\">art. 58.2 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"La razón por la cual el fiscal crea necesaria la detención\"</span>. La solicitud incluye la razón por la que el fiscal considera necesaria la detención. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3845","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Orden de detención u orden de comparecencia dictada por la Sala de Cuestiones Preliminares. La orden de detención consignará el nombre de la persona y cualquier otro dato que sirva para su identificación, una referencia expresa al crimen y una descripción concisa de los hechos, y seguirá en vigor:","o":["mientras la Corte no disponga lo contrario.","durante un plazo máximo de seis meses, renovable.","hasta que se confirmen los cargos contra la persona.","hasta la entrega de la persona a la Corte."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">mientras la Corte no disponga lo contrario</mark></span>El <span class=\"ref-norma\">art. 58.3 y 4 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"La orden de detención seguirá en vigor mientras la Corte no disponga lo contrario\"</span>. No tiene plazo: sigue en vigor mientras la Corte no disponga lo contrario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3339","p":"Estatuto del Consejo de Europa, hecho en Londres el 5 de mayo de 1949. La Asamblea Consultiva. Las deliberaciones sobre las proposiciones que han de ser dirigidas al Comité de Ministros para la inscripción de una cuestión en el programa de la Asamblea Consultiva deberán referirse únicamente:","o":["a la competencia de la Asamblea para tratar la cuestión.","a la urgencia de la cuestión planteada.","a las razones en pro o en contra de esa inscripción.","al coste de la inclusión de la cuestión en el programa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a las razones en pro o en contra de esa inscripción</mark></span>El <span class=\"ref-norma\">art. 31 de el Estatuto del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"deberán referirse únicamente a las razones en pro o en contra de esa inscripción\"</span>. Solo se debate sobre las razones a favor o en contra de la inscripción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3847","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Orden de detención u orden de comparecencia dictada por la Sala de Cuestiones Preliminares. La orden de comparecencia consignará el nombre de la persona y cualquier otro dato que sirva para su identificación, la fecha de la comparecencia, una referencia expresa al crimen y una descripción concisa de los hechos; la notificación de la orden será:","o":["por conducto del Estado de la nacionalidad del acusado.","por medio de comunicación a su abogado.","personal.","por edicto cuando no se encuentre al interesado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">personal</mark></span>El <span class=\"ref-norma\">art. 58.7 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"La notificación de la orden será personal\"</span>. La notificación de la orden de comparecencia es personal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-183","p":"Estatuto de Roma de la Corte Penal Internacional. Orden de detención o de comparecencia. El fiscal podrá pedir a la Sala de Cuestiones Preliminares que, en lugar de una orden de detención, dicte:","o":["Una orden de libertad provisional.","Una orden de comparecencia.","Una orden de presentación ante la Sala de Primera Instancia.","Una orden de localización y vigilancia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Una orden de comparecencia</mark></span>Según el <span class=\"ref-norma\">art. 58.7 (R26) del Estatuto de Roma</span>: <span class=\"ref-concepto\">\"El fiscal podrá pedir a la Sala de Cuestiones Preliminares que, en lugar de una orden de detención, dicte una orden de comparecencia\"</span>. Ficha RECUERDA R26. <i>(ficha RECUERDA R26 del temario)</i><!--t1m:lote1-->"},{"i":"1-154","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Orden de comparecencia (EX). El fiscal podrá pedir a la Sala de Cuestiones Preliminares que, en lugar de una orden de detención, dicte una orden de comparecencia. La orden de comparecencia consignará el nombre de la persona y cualquier otro dato que sirva para su identificación, una referencia expresa al crimen, una descripción concisa de los hechos y:","o":["la fecha de la comparecencia.","el lugar de custodia de la persona.","las condiciones de la libertad provisional.","el resumen de las pruebas del fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la fecha de la comparecencia</mark></span>El <span class=\"ref-norma\">art. 58.7 de el Estatuto de Roma de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"La orden de comparecencia consignará: a) El nombre de la persona y cualquier otro dato que sirva para su identificación; b) La fecha de la comparecencia; c) Una referencia expresa al crimen de la competencia de la Corte que presuntamente haya cometido, y d) Una descripción concisa de los hechos que presuntamente constituyan esos crímenes\"</span>. La orden de comparecencia consigna además la fecha de la comparecencia."},{"i":"1-306","p":"Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional. Secretario Adjunto, personal de la Fiscalía y personal de la Secretaría. Los Estados Partes no estarán obligados a eximir del impuesto sobre la renta a las pensiones o rentas vitalicias abonadas a:","o":["Secretarios adjuntos y personal de la Fiscalía y de la Secretaría en ejercicio.","Ex secretarios adjuntos, miembros del personal de la Fiscalía, miembros del personal de la Secretaría y personas a su cargo.","Ex Magistrados, ex Fiscales y ex Secretarios y personas a su cargo.","Ex miembros del personal contratado localmente y personas a su cargo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Ex secretarios adjuntos, miembros del personal de la Fiscalía, miembros del personal de la Secretaría y personas a su cargo</mark></span>Según el <span class=\"ref-norma\">art. 16.2 del Acuerdo sobre Privilegios e Inmunidades de la CPI</span>: <span class=\"ref-concepto\">\"no estarán obligados a eximir del impuesto sobre la renta a las pensiones o rentas vitalicias abonadas a ex secretarios adjuntos, miembros del personal de la Fiscalía, miembros del personal de la Secretaría y personas a su cargo\"</span>. Artículo 16.2 del Acuerdo. <i>(asterisco ✱ del temario)</i><!--t1m:lote5-->"},{"i":"1-ia-3849","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Procedimiento de detención en el Estado de detención. El detenido será llevado sin demora ante la autoridad judicial competente del Estado de detención, que determinará si, de conformidad con el derecho de ese Estado:","o":["la orden le es aplicable.","la orden ha sido dictada por la Sala competente de la Corte.","la detención se ha practicado con garantías suficientes.","procede su puesta en libertad provisional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la orden le es aplicable</mark></span>El <span class=\"ref-norma\">art. 59.2 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"que determinará si, de conformidad con el derecho de ese Estado: a) La orden le es aplicable\"</span>. La primera comprobación es que la orden le es aplicable. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3902","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Procedimiento de detención en el Estado de detención. El detenido tendrá derecho a solicitar de la autoridad competente del Estado de detención la libertad provisional antes de su entrega; al decidir, esa autoridad examinará si hay circunstancias urgentes y excepcionales y si existen las salvaguardias necesarias, y no podrá examinar:","o":["si el detenido ofrece garantías suficientes de comparecencia ante la autoridad judicial competente, salvo que se disponga otra cosa en la normativa aplicable.","si concurre peligro de fuga u obstrucción de la justicia en el Estado de detención.","si la gravedad de los crímenes imputados justifica el mantenimiento de la detención.","si la orden de detención fue dictada conforme a derecho con arreglo a los requisitos fijados para su emisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">si la orden de detención fue dictada conforme a derecho con arreglo a los requisitos fijados para su emisión</mark></span>El <span class=\"ref-norma\">art. 59.3 y 4 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"Esa autoridad no podrá examinar si la orden de detención\"</span>. No puede revisar la legalidad de la orden de detención dictada por la Corte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-222","p":"Estatuto de Roma de la Corte Penal Internacional. Procedimiento de detención en el Estado de detención. Al decidir sobre la solicitud de libertad provisional, la autoridad competente del Estado de detención examinará si, dada la gravedad de los presuntos crímenes, hay circunstancias urgentes y excepcionales que justifiquen la libertad provisional y si existen las salvaguardias necesarias. Esa autoridad:","o":["No podrá examinar si la orden de detención fue dictada conforme a derecho con arreglo a los apartados a) y b) del párrafo 1 del artículo 58.","Podrá examinar si la orden de detención fue dictada conforme a derecho con arreglo al artículo 58.","Examinará únicamente si concurren circunstancias urgentes y excepcionales, sin valorar las salvaguardias necesarias.","Podrá decidir la libertad provisional sin notificarlo a la Sala de Cuestiones Preliminares."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">No podrá examinar si la orden de detención fue dictada conforme a derecho con arreglo a los apartados a) y b) del párrafo 1 del artículo 58</mark></span>Según el <span class=\"ref-norma\">art. 59.4 del Estatuto de Roma</span>: <span class=\"ref-concepto\">\"Esa autoridad no podrá examinar si la orden de detención fue dictada conforme a derecho con arreglo a los apartados a) y b) del párrafo 1 del artículo 58\"</span>. La legalidad de la orden la controla la Corte, no el Estado de detención. <i>(asterisco ✱ del temario)</i><!--t1m:lote2-->"},{"i":"1-89","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Procedimiento de detención en el Estado de detención. El detenido tendrá derecho a solicitar de la autoridad competente del Estado de detención la libertad provisional antes de su entrega. La solicitud de libertad provisional será notificada a:","o":["El fiscal.","La Sala de Cuestiones Preliminares.","La Sala de Primera Instancia.","Al Estado miembro reclamante."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Sala de Cuestiones Preliminares.</mark></span>El <span class=\"ref-norma\">art. 59.5 de el Estatuto de Roma de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"La solicitud de libertad provisional será notificada a la Sala de Cuestiones Preliminares, que hará recomendaciones a la autoridad competente del Estado de detención\"</span>."},{"i":"1-156","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Procedimiento de detención en el Estado de detención (EX). La solicitud de libertad provisional del detenido en el Estado de detención será notificada:","o":["a la Sala de Cuestiones Preliminares, que hará recomendaciones a la autoridad competente del Estado de detención.","al fiscal, que hará recomendaciones a la autoridad competente del Estado de detención.","a la Sala de Primera Instancia, que decidirá sobre la libertad provisional.","a la Presidencia de la Corte, que hará recomendaciones al Estado de detención."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a la Sala de Cuestiones Preliminares, que hará recomendaciones a la autoridad competente del Estado de detención</mark></span>El <span class=\"ref-norma\">art. 59.5 de el Estatuto de Roma de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"La solicitud de libertad provisional será notificada a la Sala de Cuestiones Preliminares, que hará recomendaciones a la autoridad competente del Estado de detención\"</span>. Se notifica a la Sala de Cuestiones Preliminares."}]},{"a":"ART. 4 · AUTORIDADES COMPETENTES PARA LA APLICACIÓN DE LA LEY","q":[{"i":"1-103","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. ¿Cuál de las siguientes autoridades es competente para la aplicación de esta ley en los casos previstos y cuando intervinieran factores de política exterior?","o":["Ministerio de Justicia.","Ministerio del Interior.","Ministerio de Asuntos Exteriores.","Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ministerio de Asuntos Exteriores</mark></span>Según el <span class=\"ref-norma\">art. 4 de la Ley Orgánica 18/2003, de Cooperación con la Corte Penal Internacional</span>: <span class=\"ref-concepto\">\"c) El Ministerio de Asuntos Exteriores, en los casos previstos en esta ley, y, en todo caso, cuando intervinieran factores de política exterior.\"</span> (verificado con el texto del temario)."},{"i":"1-116","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. Son autoridades competentes para la aplicación de esta ley:","o":["El Gobierno.","El Ministerio de Justicia.","El Ministerio Fiscal.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>Según el <span class=\"ref-norma\">art. 4 de la Ley Orgánica 18/2003, de Cooperación con la Corte Penal Internacional</span>: <span class=\"ref-concepto\">\"Son autoridades competentes para la aplicación de esta ley: a) El Gobierno. b) El Ministerio de Justicia. [...] g) El Ministerio Fiscal.\"</span> (verificado con el texto del temario)."},{"i":"1-233","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De las autoridades competentes. Son autoridades competentes para la aplicación de esta ley, entre otras: los órganos judiciales de la jurisdicción ordinaria y, en particular, la __________.","o":["Audiencia Provincial de Madrid","Sala de lo Penal del Tribunal Supremo","Sala de Apelación de la Audiencia Nacional","Audiencia Nacional"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Audiencia Nacional</mark></span>Según el <span class=\"ref-norma\">art. 4.e) de la Ley Orgánica 18/2003</span>: <span class=\"ref-concepto\">\"Los órganos judiciales de la jurisdicción ordinaria y, en particular, la Audiencia Nacional\"</span>. Letra e) del artículo 4. <i>(asterisco ✱ del temario)</i><!--t1m:lote3-->"},{"i":"1-234","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De las autoridades competentes. Son autoridades competentes para la aplicación de esta ley, entre otras: los órganos judiciales militares y, en particular, el __________.","o":["Tribunal Militar Territorial de Madrid","Juzgado Togado Militar Central Decano","Tribunal Militar Central","Consejo Supremo de Justicia Militar"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Tribunal Militar Central</mark></span>Según el <span class=\"ref-norma\">art. 4.f) de la Ley Orgánica 18/2003</span>: <span class=\"ref-concepto\">\"Los órganos judiciales militares y, en particular, el Tribunal Militar Central\"</span>. Letra f) del artículo 4. <i>(asterisco ✱ del temario)</i><!--t1m:lote3-->"}]},{"a":"Artículo 4 — De las autoridades competentes ✱","q":[{"i":"1-140","p":"Estatuto del Consejo de Europa. El Comité de Ministros (PREGUNTA EXAMEN 2020). Cuando un Ministro de Asuntos Exteriores no pueda asistir a las sesiones del Comité de Ministros, o cuando otras circunstancias lo aconsejen, podrá designarse un suplente que actúe en su lugar; éste será, en la medida de lo posible:","o":["un miembro del Gobierno de su país.","un diplomático de su país.","un parlamentario de su país.","el embajador de su país ante el Consejo de Europa."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">un miembro del Gobierno de su país</mark></span>El <span class=\"ref-norma\">art. 14 de el Estatuto del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"Cuando un Ministro de Asuntos Exteriores no pueda asistir a las sesiones, o cuando otras circunstancias lo aconsejen, podrá designarse un suplente que actúe en su lugar; éste será, en la medida de lo posible, un miembro del Gobierno de su país\"</span>. El suplente debe ser, si es posible, miembro del Gobierno."},{"i":"1-127","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De los órganos de relación y consulta con la Corte. El Ministerio de Justicia es el único ÓRGANO DE RELACIÓN entre la Corte, por un lado, y los órganos judiciales y Ministerio Fiscal, por otro:","o":["sin perjuicio de las competencias del Ministerio de Asuntos Exteriores.","sin perjuicio de las competencias del Ministerio del Interior.","previo informe, en todo caso, del Ministerio de Asuntos Exteriores.","con exclusión de las competencias del Ministerio de Asuntos Exteriores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">previo informe, en todo caso, del Ministerio de Asuntos Exteriores</mark></span>El <span class=\"ref-norma\">art. 6.1 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"El Ministerio de Justicia es el único ÓRGANO DE RELACIÓN entre la Corte, por un lado, y los órganos judiciales y Ministerio Fiscal, por otro, sin perjuicio de las competencias del Ministerio de Asuntos Exteriores\"</span>. La coletilla es «sin perjuicio de las competencias del Ministerio de Asuntos Exteriores»."},{"i":"1-ia-3015","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De las autoridades competentes. Son autoridades competentes para la aplicación de esta ley el Gobierno, el Ministerio de Justicia y el Ministerio de Asuntos Exteriores, este último:","o":["solo cuando la Corte lo solicite expresamente.","únicamente en las solicitudes de cooperación activa, conforme al procedimiento que se establezca reglamentariamente.","en los casos previstos en la ley y, en todo caso, cuando intervinieran factores de política exterior.","siempre que intervenga el Ministerio de Defensa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en los casos previstos en la ley y, en todo caso, cuando intervinieran factores de política exterior</mark></span>El <span class=\"ref-norma\">art. 4 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"en los casos previstos en esta ley, y, en todo caso, cuando intervinieran factores de política exterior\"</span>. Asuntos Exteriores interviene en los casos previstos y siempre que haya factores de política exterior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3016","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De las autoridades competentes. El Ministerio de Defensa y el Ministerio del Interior son autoridades competentes para la aplicación de esta ley:","o":["en todos los actos de entrega de personas a la Corte.","cuando el acto de cooperación afecte a sus competencias.","solo en la ejecución de las penas privativas de libertad.","cuando lo disponga el Consejo de Ministros en cada caso."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cuando el acto de cooperación afecte a sus competencias</mark></span>El <span class=\"ref-norma\">art. 4 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"cuando el acto de cooperación afecte a sus competencias\"</span>. Su competencia depende de que el acto de cooperación afecte a sus competencias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3017","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De las autoridades competentes. Entre las autoridades competentes para la aplicación de esta ley, junto a los órganos judiciales de la jurisdicción ordinaria y, en particular, la Audiencia Nacional, figuran:","o":["los órganos judiciales militares y, en particular, el Tribunal Militar Central.","los órganos judiciales militares y, en particular, el Tribunal Supremo, Sala Quinta.","el Tribunal Constitucional y el Defensor del Pueblo.","el Consejo General del Poder Judicial y la Fiscalía General del Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los órganos judiciales militares y, en particular, el Tribunal Militar Central</mark></span>El <span class=\"ref-norma\">art. 4 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"Los órganos judiciales militares y, en particular, el Tribunal Militar Central\"</span>. La letra f) recoge a los órganos judiciales militares y, en particular, al Tribunal Militar Central. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3451","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Condiciones de ejercicio de sus funciones. Los Jueces del Tribunal Europeo de Derechos Humanos formarán parte del tribunal a título individual, y cualquier cuestión sobre la compatibilidad de sus actividades con las exigencias de independencia, imparcialidad o disponibilidad será dirimida:","o":["por el Comité de Ministros.","por el Presidente del Tribunal.","por el Tribunal.","por la Asamblea Parlamentaria."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por el Tribunal</mark></span>El <span class=\"ref-norma\">art. 21.3 y 4 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"será dirimida por el Tribunal\"</span>. La cuestión la dirime el propio Tribunal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-133","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. De la competencia, la admisibilidad y el derecho aplicable. Podrán proponer enmiendas a los Elementos de los crímenes, entre otros:","o":["Cualquier Estado.","Los magistrados, por mayoría simple.","El fiscal.","Los magistrados, por mayoría de dos tercios."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El fiscal</mark></span>El <span class=\"ref-norma\">art. 9.2 del Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"Podrán proponer enmiendas a los Elementos de los crímenes: a) Cualquier Estado Parte; b) Los magistrados, por mayoría absoluta; c) El fiscal\"</span>. Por qué fallan las otras: no cualquier Estado, sino cualquier Estado Parte; y los magistrados, por mayoría absoluta (ni simple ni de dos tercios)."}]},{"a":"Artículo 5 — De la representación y defensa procesal ✱ R2","q":[{"i":"1-ia-3019","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la representación y defensa procesal. En los supuestos en que el procedimiento ante la Corte afecte a materias propias de algún departamento ministerial:","o":["se designará a un agente de ese departamento para actuar ante la Corte, conforme al procedimiento que se establezca reglamentariamente.","ese departamento impartirá por sí solo las instrucciones.","se oirá a éste antes de impartir las instrucciones a los Abogados del Estado.","se requerirá el informe previo del Consejo de Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">se oirá a éste antes de impartir las instrucciones a los Abogados del Estado</mark></span>El <span class=\"ref-norma\">art. 5.1 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"se oirá a éste antes de impartir las citadas instrucciones\"</span>. Basta con oír al departamento afectado antes de impartir las instrucciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-235","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la representación y defensa procesal. La representación y defensa en juicio de España ante los órganos de la Corte corresponderá:","o":["A los Abogados del Estado integrados en la Abogacía General del Estado, de acuerdo con las instrucciones impartidas por el Ministerio de Justicia, previa autorización del Consejo de Ministros.","A los Abogados del Estado integrados en la Abogacía General del Estado, de acuerdo con las instrucciones impartidas conjuntamente, en cada caso, por el Ministerio de Justicia y el Ministerio de Asuntos Exteriores.","Al Ministerio Fiscal, de acuerdo con las instrucciones impartidas por el Fiscal General del Estado y el Ministerio de Justicia.","A los Abogados del Estado destinados en el Ministerio de Asuntos Exteriores, de acuerdo con las instrucciones de este departamento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A los Abogados del Estado integrados en la Abogacía General del Estado, de acuerdo con las instrucciones impartidas conjuntamente, en cada caso, por el Ministerio de Justicia y el Ministerio de Asuntos Exteriores</mark></span>Según el <span class=\"ref-norma\">art. 5.1 de la Ley Orgánica 18/2003</span>: <span class=\"ref-concepto\">\"corresponderá a los Abogados del Estado integrados en la Abogacía General del Estado y de acuerdo con las instrucciones impartidas conjuntamente, en cada caso, por el Ministerio de Justicia y el Ministerio de Asuntos Exteriores\"</span>. Si el procedimiento afecta a materias propias de otro departamento, se oirá a éste antes de impartir las instrucciones. <i>(asterisco ✱ del temario)</i><!--t1m:lote3-->"},{"i":"1-ia-3018","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la representación y defensa procesal. La representación y defensa en juicio de España ante los órganos de la Corte corresponderá a los Abogados del Estado integrados en la Abogacía General del Estado, de acuerdo con las instrucciones impartidas conjuntamente, en cada caso, por:","o":["el Ministerio de Justicia y el Ministerio del Interior.","el Consejo de Ministros y el Ministerio de Justicia.","el Ministerio de Asuntos Exteriores y el Ministerio de Defensa, salvo que se disponga otra cosa en la normativa aplicable.","el Ministerio de Justicia y el Ministerio de Asuntos Exteriores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el Ministerio de Justicia y el Ministerio de Asuntos Exteriores</mark></span>El <span class=\"ref-norma\">art. 5.1 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"de acuerdo con las instrucciones impartidas conjuntamente, en cada caso, por el Ministerio de Justicia y el Ministerio de Asuntos Exteriores\"</span>. Las instrucciones son conjuntas de Justicia y Asuntos Exteriores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-189","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la representación y defensa procesal. El Gobierno, por motivos excepcionales y oído el Abogado General del Estado, podrá acordar que una persona, especialmente designada al efecto, actúe como:","o":["Abogado del Estado en cualquier procedimiento ante los órganos de la Corte.","Representante de España ante la Asamblea de los Estados Partes.","Agente del Ministerio Fiscal en las actuaciones de cooperación con la Corte.","Agente de España en un determinado procedimiento ante los órganos de la Corte."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Agente de España en un determinado procedimiento ante los órganos de la Corte</mark></span>Según el <span class=\"ref-norma\">art. 5.2 (R2) de la Ley Orgánica 18/2003</span>: <span class=\"ref-concepto\">\"actúe como agente de España en un determinado procedimiento ante los órganos de la Corte\"</span>. Ficha RECUERDA R2. <i>(ficha RECUERDA R2 del temario)</i><!--t1m:lote1-->"},{"i":"1-ia-3020","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la representación y defensa procesal. El Gobierno, por motivos excepcionales y oído el Abogado General del Estado, podrá acordar que una persona, especialmente designada al efecto:","o":["sustituya a la Abogacía General del Estado en todos los procedimientos ante la Corte, sin perjuicio de lo dispuesto en otras disposiciones.","actúe como agente de España en un determinado procedimiento ante los órganos de la Corte.","asuma la dirección de la defensa en el procedimiento interno de entrega.","represente a España ante la Asamblea de los Estados Partes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">actúe como agente de España en un determinado procedimiento ante los órganos de la Corte</mark></span>El <span class=\"ref-norma\">art. 5.2 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"podrá acordar que una persona, especialmente designada al efecto, actúe como agente de España en un determinado procedimiento ante los órganos de la Corte\"</span>. La persona designada actúa como agente en un procedimiento concreto y asume las funciones de Abogado del Estado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 12 — De la libertad provisional ✱","q":[{"i":"1-111","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. ¿A quién corresponde formular la petición de inhibición una vez aprobado el Acuerdo del Consejo de Ministros y realizar las restantes actuaciones previstas en el Estatuto para dar cumplimiento a dicho Acuerdo?","o":["Al Fiscal general del Estado.","Al Ministro de Asuntos Exteriores.","Al Ministerio de Justicia.","Al Juez Central de Instrucción."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al Ministerio de Justicia.</mark></span>El <span class=\"ref-norma\">art. 8.3 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"Una vez aprobado el Acuerdo del Consejo de Ministros del apartado anterior, corresponderá al Ministerio de Justicia formular la petición de inhibición y realizar las restantes actuaciones previstas en el Estatuto para dar cumplimiento a dicho Acuerdo\"</span>."},{"i":"1-ia-3040","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la libertad provisional. Si el detenido solicitara su libertad provisional, el Juez Central de Instrucción acordará remitir la solicitud a la Corte, a través del Ministerio de Justicia, con indicación del plazo para recibir sus recomendaciones, que no será inferior a:","o":["diez días.","veinte días.","quince días.","treinta días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">veinte días</mark></span>El <span class=\"ref-norma\">art. 12.1 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"con indicación del plazo para recibir sus recomendaciones, que no será inferior a veinte días\"</span>. El plazo mínimo para recibir las recomendaciones de la Corte es de veinte días. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-240","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la libertad provisional. Si el detenido solicitara, en la comparecencia prevista en el artículo anterior, su libertad provisional, el Juez Central de Instrucción acordará remitir dicha solicitud a la Corte, a través del Ministerio de Justicia, con indicación del plazo para recibir sus recomendaciones, que no será inferior a __________.","o":["veinte días","diez días","treinta días","setenta y dos horas"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">veinte días</mark></span>Según el <span class=\"ref-norma\">art. 12.1 de la Ley Orgánica 18/2003</span>: <span class=\"ref-concepto\">\"con indicación del plazo para recibir sus recomendaciones, que no será inferior a veinte días\"</span>. El plazo lo fija el Juez Central de Instrucción, con un mínimo de veinte días. <i>(asterisco ✱ del temario)</i><!--t1m:lote3-->"},{"i":"1-ia-3041","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la libertad provisional. En la misma resolución en que remite a la Corte la solicitud de libertad provisional, el Juez Central de Instrucción:","o":["acordará la prisión provisional del detenido por el tiempo estrictamente necesario para recibir las recomendaciones de la Corte.","acordará la libertad provisional con fianza hasta recibir las recomendaciones de la Corte, en los términos que establezca la propia norma.","dejará sin efecto la detención hasta recibir las recomendaciones de la Corte.","acordará la prisión provisional del detenido por un plazo de ciento ochenta días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">acordará la prisión provisional del detenido por el tiempo estrictamente necesario para recibir las recomendaciones de la Corte</mark></span>El <span class=\"ref-norma\">art. 12.1 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"acordará la prisión provisional del detenido por el tiempo estrictamente necesario para recibir las recomendaciones de la Corte sobre dicha solicitud\"</span>. Mientras tanto el detenido queda en prisión provisional el tiempo estrictamente necesario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3042","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la libertad provisional. Una vez recibidas las recomendaciones de la Corte o concluido el plazo señalado, el Juez Central de Instrucción, previa valoración de dichas recomendaciones, podrá acordar la libertad provisional del detenido cuando:","o":["lo solicite el Ministerio Fiscal y no se oponga la Corte.","haya transcurrido el plazo de setenta y dos horas desde la detención.","el detenido ofrezca fianza suficiente y consienta la entrega.","existan circunstancias urgentes y excepcionales que lo justifiquen."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">existan circunstancias urgentes y excepcionales que lo justifiquen</mark></span>El <span class=\"ref-norma\">art. 12.2 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"podrá acordar la libertad provisional del detenido cuando existan circunstancias urgentes y excepcionales que lo justifiquen\"</span>. La libertad provisional exige circunstancias urgentes y excepcionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3043","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la libertad provisional. Si en el plazo establecido en las reglas de procedimiento y prueba la Corte no hubiera remitido la documentación para la entrega, el Juez Central de Instrucción podrá acordar la libertad provisional y las medidas cautelares adecuadas, que se mantendrán por un tiempo máximo de:","o":["noventa días.","sesenta días.","ciento ochenta días.","trescientos sesenta y cinco días."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">ciento ochenta días</mark></span>El <span class=\"ref-norma\">art. 12.3 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"que se mantendrán por un tiempo máximo de ciento ochenta días\"</span>. El tiempo máximo es de ciento ochenta días, sin perjuicio de volver a decretar la prisión al recibir la documentación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-129","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la libertad provisional. Si en el plazo establecido en las reglas de procedimiento y prueba la Corte no hubiera remitido la documentación para la entrega, el Juez Central de Instrucción podrá acordar la libertad provisional y las medidas cautelares adecuadas, que se mantendrán por un tiempo máximo de:","o":["noventa días naturales, sin perjuicio de volver a decretar la prisión una vez recibida la documentación de la Corte.","ciento veinte días naturales, sin perjuicio de volver a decretar la prisión una vez recibida la documentación de la Corte.","ciento ochenta días, sin perjuicio de volver a decretar la prisión una vez recibida la documentación de la Corte.","ciento ochenta días, sin que pueda volver a decretarse la prisión aunque se reciba la documentación de la Corte."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">ciento ochenta días, sin perjuicio de volver a decretar la prisión una vez recibida la documentación de la Corte</mark></span>El <span class=\"ref-norma\">art. 12.3 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"el Juez Central de Instrucción podrá acordar la libertad provisional y las medidas cautelares adecuadas, que se mantendrán por un tiempo máximo de ciento ochenta días, sin perjuicio de volver a decretar la prisión una vez recibida la documentación de la Corte\"</span>. Ciento ochenta días como máximo, pudiendo volver a decretarse la prisión al recibir la documentación."},{"i":"1-ia-3950","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Detención provisional. La persona sometida a detención provisional podrá ser puesta en libertad si el Estado requerido no hubiere recibido la solicitud de entrega y los documentos que la justifiquen dentro del plazo fijado en las reglas de procedimiento y prueba; esa libertad no obstará para que:","o":["sea nuevamente detenida siempre que la Sala de Cuestiones Preliminares dicte una nueva orden de detención, salvo que se disponga otra cosa en la normativa aplicable.","sea citada a comparecer ante la Corte mediante una orden de comparecencia sin restricciones.","sea sometida a medidas cautelares distintas de la detención hasta que se formule la solicitud.","sea nuevamente detenida y entregada una vez que el Estado requerido reciba la solicitud de entrega y los documentos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">sea nuevamente detenida y entregada una vez que el Estado requerido reciba la solicitud de entrega y los documentos</mark></span>El <span class=\"ref-norma\">art. 92.3 y 4 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"no obstará para que sea nuevamente detenida y entregada una vez que el Estado requerido reciba la soli\"</span>. La libertad no impide una nueva detención y entrega al recibirse la solicitud y documentos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-241","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la libertad provisional. Cuando se acordare la libertad provisional, se informará a la Sala de Cuestiones Preliminares y, posteriormente, __________.","o":["cada seis meses","en el plazo de diez días","al concluir la investigación","cuantas veces ésta lo solicite"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cuantas veces ésta lo solicite</mark></span>Según el <span class=\"ref-norma\">art. 12.4 de la Ley Orgánica 18/2003</span>: <span class=\"ref-concepto\">\"se informará a la Sala de Cuestiones Preliminares y, posteriormente, cuantas veces ésta lo solicite\"</span>. Seguimiento de la libertad provisional por la Corte. <i>(asterisco ✱ del temario)</i><!--t1m:lote3-->"},{"i":"1-ia-3044","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la libertad provisional. Cuando se acordare la libertad provisional, se informará a la Sala de Cuestiones Preliminares y, posteriormente:","o":["cada treinta días.","cuantas veces ésta lo solicite.","cada vez que se modifiquen las medidas cautelares.","cuando se dicte el auto de entrega."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cuantas veces ésta lo solicite</mark></span>El <span class=\"ref-norma\">art. 12.4 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"se informará a la Sala de Cuestiones Preliminares y, posteriormente, cuantas veces ésta lo solicite\"</span>. La información posterior se facilita cuantas veces lo solicite la Sala. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 25 — De la celebración del juicio y otras actuaciones procesales en España R6","q":[{"i":"1-170","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la celebración del juicio y otras actuaciones procesales en España. Si la Corte propusiere la celebración del juicio u otras actuaciones procesales en España:","o":["El Ministerio del Interior, previa consulta con los Ministerios de Justicia y de Asuntos Exteriores y otras autoridades competentes, comunicará a la Corte la decisión al respecto.","El Ministerio de Asuntos Exteriores, previa consulta con los Ministerios de Justicia y de Defensa y el Consejo General del Poder Judicial, comunicará a la Corte la decisión al respecto.","El Ministerio de Justicia, previa consulta con los Ministerios de Asuntos Exteriores y del Interior y otras autoridades competentes, comunicará a la Corte la decisión al respecto.","El Gobierno, previa consulta con el Ministerio Fiscal y el Juzgado Central de Instrucción, comunicará a la Corte la decisión al respecto."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Ministerio de Justicia, previa consulta con los Ministerios de Asuntos Exteriores y del Interior y otras autoridades competentes, comunicará a la Corte la decisión al respecto</mark></span>Según el <span class=\"ref-norma\">art. 25 de la Ley Orgánica 18/2003</span>: <span class=\"ref-concepto\">\"el Ministerio de Justicia, previa consulta con los Ministerios de Asuntos Exteriores y del Interior y otras autoridades competentes, comunicará a la Corte la decisión al respecto\"</span>. Ficha RECUERDA R6. <i>(marca EXOF / sello «PREGUNTA EXAMEN» del temario)</i><!--t1m:lote1-->"},{"i":"1-ia-3110","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la celebración del juicio y otras actuaciones procesales en España. Si la Corte propusiere la celebración del juicio u otras actuaciones procesales en España, el Ministerio de Justicia, previa consulta con los Ministerios de Asuntos Exteriores y del Interior y otras autoridades competentes:","o":["elevará la propuesta al Consejo de Ministros para su aprobación.","remitirá la propuesta a la Audiencia Nacional para su informe.","aceptará la propuesta y fijará la sede de las sesiones.","comunicará a la Corte la decisión al respecto."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">comunicará a la Corte la decisión al respecto</mark></span>El <span class=\"ref-norma\">art. 25 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"comunicará a la Corte la decisión al respecto\"</span>. Justicia comunica la decisión a la Corte; los aspectos no jurisdiccionales se someten al acuerdo específico. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3111","p":"Ley Orgánica 18/2003, de 10 de diciembre, de Cooperación con la Corte Penal Internacional. De la celebración del juicio y otras actuaciones procesales en España. En el caso de que la Corte celebre el juicio u otras actuaciones procesales en España, los aspectos no jurisdiccionales de dichas actuaciones:","o":["estarán sometidos a las instrucciones del Consejo General del Poder Judicial.","se regirán por las normas de la Ley Orgánica del Poder Judicial.","estarán sometidos al acuerdo específico que se celebre con la Corte.","serán regulados por Real Decreto del Gobierno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">estarán sometidos al acuerdo específico que se celebre con la Corte</mark></span>El <span class=\"ref-norma\">art. 25 de la Ley Orgánica 18/2003</span> dispone: <span class=\"ref-concepto\">\"los aspectos no jurisdiccionales de dichas actuaciones estarán sometidos al acuerdo específico que se celebre con la Corte\"</span>. Los aspectos no jurisdiccionales dependen del acuerdo específico con la Corte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 20, 23 y 24 — Igualdad ante la ley, igualdad entre mujeres y hombres y derechos del niño ✱ R7 R8 R9","q":[{"i":"1-173","p":"Carta de los Derechos Fundamentales de la Unión Europea. Preámbulo (ciudadanía y espacio de libertad). Al instituir la ciudadanía de la Unión y crear un espacio de libertad, seguridad y justicia, la Unión sitúa a __________ en el centro de su actuación.","o":["el ciudadano europeo","el Estado de Derecho","la dignidad humana","la persona"],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la persona</mark></span>Según el <span class=\"ref-norma\">Preámbulo de la Carta de los Derechos Fundamentales de la UE</span>: <span class=\"ref-concepto\">\"sitúa a la persona en el centro de su actuación\"</span>. Preámbulo de la Carta (sello «PREGUNTA EXAMEN»). <i>(marca EXOF / sello «PREGUNTA EXAMEN» del temario)</i><!--t1m:lote1-->"},{"i":"1-ia-3201","p":"Carta de los Derechos Fundamentales de la Unión Europea. Igualdad ante la ley. En el Título III de la Carta, dedicado a la Igualdad, se proclama que:","o":["todas las personas son iguales ante la ley.","todos los ciudadanos de la Unión son iguales ante la ley.","todas las personas son iguales ante la ley y los tribunales.","todos los seres humanos nacen libres e iguales en dignidad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">todas las personas son iguales ante la ley</mark></span>El <span class=\"ref-norma\">art. 20 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Todas las personas son iguales ante la ley\"</span>. La Carta habla de «todas las personas», no solo de los ciudadanos de la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-192","p":"Carta de los Derechos Fundamentales de la Unión Europea. Diversidad cultural, religiosa y lingüística. La Unión respeta la diversidad __________.","o":["cultural, religiosa y lingüística","cultural, étnica y lingüística","cultural, religiosa y política","social, religiosa y lingüística"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cultural, religiosa y lingüística</mark></span>Según el <span class=\"ref-norma\">art. 22 (R7) de la Carta de los Derechos Fundamentales de la UE</span>: <span class=\"ref-concepto\">\"La Unión respeta la diversidad cultural, religiosa y lingüística\"</span>. Ficha RECUERDA R7. <i>(ficha RECUERDA R7 del temario)</i><!--t1m:lote1-->"},{"i":"1-ia-3204","p":"Carta de los Derechos Fundamentales de la Unión Europea. Diversidad cultural, religiosa y lingüística. En el Título III de la Carta, la Unión respeta:","o":["la diversidad cultural, étnica y lingüística, sin perjuicio de lo dispuesto en otras disposiciones.","la diversidad cultural, religiosa y lingüística.","la identidad cultural, religiosa y nacional.","la diversidad cultural, social y religiosa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la diversidad cultural, religiosa y lingüística</mark></span>El <span class=\"ref-norma\">art. 22 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La Unión respeta la diversidad cultural, religiosa y lingüística\"</span>. Las tres diversidades son cultural, religiosa y lingüística. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-193","p":"Carta de los Derechos Fundamentales de la Unión Europea. Igualdad entre mujeres y hombres. La igualdad entre mujeres y hombres deberá garantizarse en todos los ámbitos, inclusive en materia de:","o":["Empleo, formación y promoción profesional.","Trabajo, retribución y seguridad social.","Empleo, educación y retribución.","Empleo, trabajo y retribución."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Empleo, trabajo y retribución</mark></span>Según el <span class=\"ref-norma\">art. 23 (R8) de la Carta de los Derechos Fundamentales de la UE</span>: <span class=\"ref-concepto\">\"inclusive en materia de empleo, trabajo y retribución\"</span>. Ficha RECUERDA R8. <i>(ficha RECUERDA R8 del temario)</i><!--t1m:lote1-->"},{"i":"1-ia-3205","p":"Carta de los Derechos Fundamentales de la Unión Europea. Igualdad entre mujeres y hombres. El principio de igualdad entre mujeres y hombres no impide el mantenimiento o la adopción de medidas que supongan ventajas concretas en favor:","o":["del sexo menos representado.","del sexo femenino.","de los grupos desfavorecidos.","de las personas con discapacidad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">del sexo menos representado</mark></span>El <span class=\"ref-norma\">art. 23 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"medidas que supongan ventajas concretas en favor del sexo menos representado\"</span>. La Carta neutra: el sexo menos representado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3207","p":"Carta de los Derechos Fundamentales de la Unión Europea. Derechos del niño. En todos los actos relativos a los niños llevados a cabo por autoridades públicas o instituciones privadas, el interés superior del niño constituirá:","o":["la consideración única.","un criterio orientador.","una consideración primordial.","una garantía fundamental, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">una consideración primordial</mark></span>El <span class=\"ref-norma\">art. 24.2 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el interés superior del niño constituirá una consideración primordial\"</span>. Es «una» consideración primordial, no la única. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3208","p":"Carta de los Derechos Fundamentales de la Unión Europea. Derechos del niño. Todo niño tiene derecho a mantener de forma periódica relaciones personales y contactos directos con su padre y con su madre, salvo si ello es:","o":["contrario a la resolución judicial.","contrario a sus intereses.","contrario a su opinión.","imposible por la distancia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">contrario a sus intereses</mark></span>El <span class=\"ref-norma\">art. 24.3 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"salvo si ello es contrario a sus intereses\"</span>. La excepción es que sea contrario a sus intereses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-102","p":"Carta de los derechos fundamentales de la Unión Europea. Derechos del niño. Señale la INCORRECTA:","o":["Los niños tienen derecho a la protección y a los cuidados necesarios para su bienestar.","Los niños podrán expresar su opinión libremente. Esta será tenida en cuenta para los asuntos que les afecten, en función de su edad y madurez.","En todos los actos relativos a los niños llevados a cabo por autoridades públicas o instituciones privadas, el interés superior del niño constituirá una consideración subsidiaria.","Todo niño tiene derecho a mantener de forma periódica relaciones personales y contactos directos con su padre y con su madre, salvo si ello es contrario a sus intereses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">En todos los actos relativos a los niños llevados a cabo por autoridades públicas o instituciones privadas, el interés superior del niño constituirá una consideración subsidiaria.</mark></span>El <span class=\"ref-norma\">art. 24 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los niños tienen derecho a la protección y a los cuidados necesarios para su bienestar. Podrán expresar su opinión libremente. Ésta será tenida en cuenta para los asuntos que les afecten, en función de su edad y madurez. [...] el interés superior del niño constituirá una consideración primordial. [...] Todo niño tiene derecho a mantener de forma periódica relaciones personales y contactos directos con su padre y con su madre, salvo si ello es contrario a sus intereses\"</span>."},{"i":"1-ia-3206","p":"Carta de los Derechos Fundamentales de la Unión Europea. Derechos del niño. Los niños tienen derecho a la protección y a los cuidados necesarios para su bienestar. Podrán expresar su opinión libremente, y ésta será tenida en cuenta para los asuntos que les afecten, en función de:","o":["su edad y capacidad de discernimiento.","su grado de desarrollo y entorno familiar.","su edad y condición social.","su edad y madurez."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">su edad y madurez</mark></span>El <span class=\"ref-norma\">art. 24.1 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"en función de su edad y madurez\"</span>. El criterio es edad y madurez. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 29, 32, 34 y 37 — Colocación, trabajo infantil, ayuda social y medio ambiente ✱ R10","q":[{"i":"1-80","p":"Carta de los derechos Fundamentales de la Unión Europea. Solidaridad. Toda persona tiene derecho a acceder a un servicio _________ de colocación.","o":["Subvencionado.","Integral.","Retribuido.","Gratuito."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Gratuito.</mark></span>El <span class=\"ref-norma\">art. 29 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Toda persona tiene derecho a acceder a un servicio gratuito de colocación\"</span>."},{"i":"1-ia-3213","p":"Carta de los Derechos Fundamentales de la Unión Europea. Derecho de acceso a los servicios de colocación. Toda persona tiene derecho a acceder a un servicio de colocación:","o":["gratuito.","público y gratuito.","público.","eficaz y gratuito."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">gratuito</mark></span>El <span class=\"ref-norma\">art. 29 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Toda persona tiene derecho a acceder a un servicio gratuito de colocación\"</span>. El servicio ha de ser gratuito; la Carta no exige que sea público. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3215","p":"Carta de los Derechos Fundamentales de la Unión Europea. Condiciones de trabajo justas y equitativas. Todo trabajador tiene derecho a trabajar en condiciones que respeten su:","o":["salud, seguridad e integridad.","seguridad, intimidad y dignidad.","salud, seguridad y dignidad.","salud, dignidad y libertad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">salud, seguridad y dignidad</mark></span>El <span class=\"ref-norma\">art. 31.1 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Todo trabajador tiene derecho a trabajar en condiciones que respeten su salud, seguridad y dignidad\"</span>. Los tres bienes son salud, seguridad y dignidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3216","p":"Carta de los Derechos Fundamentales de la Unión Europea. Condiciones de trabajo justas y equitativas. Todo trabajador tiene derecho a la limitación de la duración máxima del trabajo y a períodos de descanso diarios y semanales, así como a:","o":["un período de vacaciones anuales de al menos cuatro semanas.","un período de vacaciones anuales retribuidas.","un permiso retribuido por asuntos propios.","una jornada máxima semanal de cuarenta horas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un período de vacaciones anuales retribuidas</mark></span>El <span class=\"ref-norma\">art. 31.2 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"así como a un período de vacaciones anuales retribuidas\"</span>. La Carta no fija semanas concretas; reconoce vacaciones anuales retribuidas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-194","p":"Carta de los Derechos Fundamentales de la Unión Europea. Condiciones de trabajo justas y equitativas. Todo trabajador tiene derecho a trabajar en condiciones que respeten __________.","o":["su salud, integridad y dignidad","su seguridad, higiene y dignidad","su salud, seguridad y dignidad","su salud, seguridad y libertad"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">su salud, seguridad y dignidad</mark></span>Según el <span class=\"ref-norma\">art. 31.1 (R10) de la Carta de los Derechos Fundamentales de la UE</span>: <span class=\"ref-concepto\">\"Todo trabajador tiene derecho a trabajar en condiciones que respeten su salud, seguridad y dignidad\"</span>. Ficha RECUERDA R10. <i>(ficha RECUERDA R10 del temario)</i><!--t1m:lote1-->"},{"i":"1-259","p":"Carta de los Derechos Fundamentales de la Unión Europea. Prohibición del trabajo infantil. Se prohíbe el trabajo infantil. La edad mínima de admisión al trabajo no podrá ser inferior a la edad en que concluye el período de __________, sin perjuicio de disposiciones más favorables para los jóvenes y salvo excepciones limitadas.","o":["formación profesional","escolaridad obligatoria","enseñanza primaria","minoría de edad"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">escolaridad obligatoria</mark></span>Según el <span class=\"ref-norma\">art. 32 de la Carta de los Derechos Fundamentales de la UE</span>: <span class=\"ref-concepto\">\"no podrá ser inferior a la edad en que concluye el período de escolaridad obligatoria\"</span>. Artículo 32 de la Carta. <i>(asterisco ✱ del temario)</i><!--t1m:lote3-->"},{"i":"1-ia-3217","p":"Carta de los Derechos Fundamentales de la Unión Europea. Prohibición del trabajo infantil y protección de los jóvenes en el trabajo. Se prohíbe el trabajo infantil. La edad mínima de admisión al trabajo no podrá ser inferior a la edad en que concluye el período de escolaridad obligatoria, sin perjuicio de disposiciones más favorables para los jóvenes y:","o":["salvo excepciones limitadas.","salvo autorización administrativa.","salvo en el ámbito familiar.","salvo actividades artísticas o culturales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">salvo excepciones limitadas</mark></span>El <span class=\"ref-norma\">art. 32 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"sin perjuicio de disposiciones más favorables para los jóvenes y salvo excepciones limitadas\"</span>. Solo caben excepciones limitadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3222","p":"Carta de los Derechos Fundamentales de la Unión Europea. Seguridad social y ayuda social. Con el fin de combatir la exclusión social y la pobreza, la Unión reconoce y respeta el derecho a una ayuda social y a una ayuda de vivienda para garantizar una existencia digna a todos aquellos que:","o":["no tengan empleo estable.","residan legalmente en la Unión.","se encuentren en situación de dependencia.","no dispongan de recursos suficientes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no dispongan de recursos suficientes</mark></span>El <span class=\"ref-norma\">art. 34.3 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"para garantizar una existencia digna a todos aquellos que no dispongan de recursos suficientes\"</span>. El destinatario es quien carezca de recursos suficientes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-77","p":"Carta de los derechos fundamentales de la Unión Europea. Protección del medio ambiente. En las políticas de la Unión se integrarán y garantizarán, conforme al principio de desarrollo sostenible:","o":["Una protección integral del medio ambiente y la mejora de su calidad.","Un nivel regular de protección del medio ambiente y la mejora de su calidad.","Un nivel elevado de erradicación del medio ambiente y la mejora de su calidad.","Un nivel elevado de protección del medio ambiente y la mejora de su calidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Un nivel elevado de protección del medio ambiente y la mejora de su calidad.</mark></span>El <span class=\"ref-norma\">art. 37 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"En las políticas de la Unión se integrarán y garantizarán, conforme al principio de desarrollo sostenible, un nivel elevado de protección del medio ambiente y la mejora de su calidad\"</span>."},{"i":"1-ia-3225","p":"Carta de los Derechos Fundamentales de la Unión Europea. Protección del medio ambiente. En las políticas de la Unión se integrarán y garantizarán, conforme al principio de desarrollo sostenible, un nivel elevado de protección del medio ambiente y:","o":["la mejora de su calidad.","la conservación de la biodiversidad.","la reducción de emisiones contaminantes.","la preservación de los recursos naturales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la mejora de su calidad</mark></span>El <span class=\"ref-norma\">art. 37 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"un nivel elevado de protección del medio ambiente y la mejora de su calidad\"</span>. Se añade la mejora de su calidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 35 — Protección de la salud","q":[{"i":"1-137","p":"Carta de los Derechos Fundamentales de la Unión Europea. Protección de la salud (PREGUNTA EXAMEN 2020). Toda persona tiene derecho a acceder a la prevención sanitaria y a beneficiarse de la atención sanitaria en las condiciones establecidas por:","o":["las legislaciones y prácticas nacionales.","el Derecho de la Unión.","las legislaciones nacionales y el Derecho de la Unión.","los Tratados y las legislaciones nacionales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las legislaciones y prácticas nacionales</mark></span>El <span class=\"ref-norma\">art. 35 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Toda persona tiene derecho a acceder a la prevención sanitaria y a beneficiarse de la atención sanitaria en las condiciones establecidas por las legislaciones y prácticas nacionales\"</span>. El acceso a la sanidad se condiciona a las legislaciones y prácticas nacionales."},{"i":"1-ia-3223","p":"Carta de los Derechos Fundamentales de la Unión Europea. Protección de la salud. Al definirse y ejecutarse todas las políticas y acciones de la Unión se garantizará:","o":["el acceso universal a la atención sanitaria.","la gratuidad de la atención sanitaria básica.","un nivel elevado de protección de la salud humana.","la cooperación sanitaria entre los Estados miembros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un nivel elevado de protección de la salud humana</mark></span>El <span class=\"ref-norma\">art. 35 de la Carta de los Derechos Fundamentales de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"se garantizará un nivel elevado de protección de la salud humana\"</span>. La garantía es un nivel elevado de protección de la salud humana. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 7, 8 y 9 — Retirada y suspensión ✱ R12","q":[{"i":"1-126","p":"Estatuto del Consejo de Europa. Cualquier Miembro del Consejo de Europa podrá retirarse del mismo notificando su decisión al Secretario General. La notificación surtirá efecto:","o":["Al finalizar el año financiero en curso, si se realiza en los últimos tres meses del año.","Al concluir el siguiente año fiscal.","Al recibir la notificación por el Secretario General.","Al concluir el año financiero en curso, si tuvo lugar en los primeros nueve meses de este año, y al finalizar el año financiero siguiente, si se realizó en los tres últimos meses."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Al concluir el año financiero en curso, si tuvo lugar en los primeros nueve meses de este año, y al finalizar el año financiero siguiente, si se realizó en los tres últimos meses.</mark></span>El <span class=\"ref-norma\">art. 7 de el Estatuto del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"Cualquier Miembro del Consejo de Europa podrá retirarse del mismo notificando su decisión al Secretario General. La notificación surtirá efecto al concluir el año financiero en curso, si tuvo lugar en los primeros nueve meses de este año, y al finalizar el año financiero siguiente, si se realizó en los tres últimos meses\"</span>."},{"i":"1-ia-3303","p":"Estatuto del Consejo de Europa, hecho en Londres el 5 de mayo de 1949. Retirada. La notificación de retirada de un Miembro surtirá efecto al concluir el año financiero en curso, si tuvo lugar en los primeros nueve meses de este año, y:","o":["al finalizar el año financiero siguiente, si se realizó en los seis últimos meses, conforme al procedimiento que se establezca reglamentariamente.","a los seis meses de la notificación, en todo caso.","al finalizar el año financiero siguiente, si se realizó en los tres últimos meses.","al concluir el año financiero en curso, si se realizó en los tres últimos meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al finalizar el año financiero siguiente, si se realizó en los tres últimos meses</mark></span>El <span class=\"ref-norma\">art. 7 de el Estatuto del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"La notificación surtirá efecto al concluir el año financiero en curso, si tuvo lugar en los primeros nueve meses de este año, y al finalizar el año financiero siguiente, si se realizó en los tres últimos meses\"</span>. Nueve primeros meses: fin del año en curso; tres últimos meses: fin del año siguiente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-269","p":"Estatuto del Consejo de Europa. Suspensión del derecho de representación. El Comité de Ministros podrá dejar en suspenso el derecho de representación del Miembro que infrinja gravemente lo dispuesto en el artículo 3 e invitarle a retirarse. Si no atiende a dicha invitación, el Comité puede decidir que el Miembro de que se trata ha cesado de pertenecer al Consejo:","o":["A partir de una fecha que determinará el propio Comité.","En la fecha en que lo acuerde la Asamblea Consultiva por mayoría de dos tercios.","Al finalizar el año financiero en curso.","Transcurridos seis meses desde la invitación a retirarse."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A partir de una fecha que determinará el propio Comité</mark></span>Según el <span class=\"ref-norma\">art. 8 del Estatuto del Consejo de Europa</span>: <span class=\"ref-concepto\">\"ha cesado de pertenecer al Consejo a partir de una fecha que determinará el propio Comité\"</span>. El artículo 3 recoge el imperio del Derecho y el respeto de los derechos humanos. <i>(asterisco ✱ del temario)</i><!--t1m:lote4-->"},{"i":"1-ia-3304","p":"Estatuto del Consejo de Europa, hecho en Londres el 5 de mayo de 1949. Suspensión y cese. El Comité de Ministros podrá dejar en suspenso el derecho de representación del Miembro del Consejo de Europa que infrinja gravemente lo dispuesto sobre el imperio del Derecho y los derechos humanos, e invitarle a retirarse; si no atiende a dicha invitación, el Comité:","o":["debe elevar la cuestión a la Asamblea Consultiva para que decida su expulsión.","puede decidir que el Miembro ha cesado de pertenecer al Consejo a partir de una fecha que determinará el propio Comité.","puede decidir su expulsión inmediata por unanimidad.","debe esperar a que transcurra un año financiero para dar por concluida su pertenencia, sin perjuicio de lo dispuesto en otras disposiciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">puede decidir que el Miembro ha cesado de pertenecer al Consejo a partir de una fecha que determinará el propio Comité</mark></span>El <span class=\"ref-norma\">art. 8 de el Estatuto del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"Si no atiende a dicha invitación, el Comité puede decidir que el Miembro de que se trata ha cesado de pertenecer al Consejo a partir de una fecha que determinará el propio Comité\"</span>. El cese lo decide el Comité de Ministros, que fija la fecha. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3270","p":"Estatuto del Consejo de Europa, hecho en Londres el 5 de mayo de 1949. Composición. El término «Miembro» empleado en el Estatuto se refiere también a los Miembros asociados, salvo cuando se trate de:","o":["la representación en la Asamblea Consultiva, salvo que se disponga otra cosa en la normativa aplicable.","el pago de contribuciones al presupuesto.","la participación en el Secretariado.","la representación en el Comité de Ministros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la representación en el Comité de Ministros</mark></span>El <span class=\"ref-norma\">art. 5.b de el Estatuto del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"salvo cuando se trate de la representación en el COMITÉ DE MINISTROS\"</span>. La excepción es la representación en el Comité de Ministros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3305","p":"Estatuto del Consejo de Europa, hecho en Londres el 5 de mayo de 1949. Obligaciones financieras. Cuando un Miembro no cumpla sus obligaciones financieras, el Comité de Ministros podrá suspender su derecho de representación en el Comité y en la Asamblea Consultiva:","o":["durante el tiempo en que deje de satisfacer dichas obligaciones.","durante un plazo máximo de un año.","hasta que la Asamblea Consultiva decida lo contrario, en los términos que establezca la propia norma.","de forma definitiva si el impago supera dos años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">durante el tiempo en que deje de satisfacer dichas obligaciones</mark></span>El <span class=\"ref-norma\">art. 9 de el Estatuto del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"durante el tiempo en que deje de satisfacer dichas obligaciones\"</span>. La suspensión dura mientras se mantenga el incumplimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-270","p":"Estatuto del Consejo de Europa. Incumplimiento de las obligaciones financieras. Cuando un Miembro no cumpla sus obligaciones financieras, el Comité de Ministros podrá suspender su derecho de representación:","o":["Únicamente en la Asamblea Consultiva hasta el siguiente año financiero.","En el Comité de Ministros, pero no en la Asamblea Consultiva, hasta que abone su contribución.","En el Consejo de Europa, de forma definitiva, previa recomendación de la Asamblea.","En el Comité y en la Asamblea Consultiva durante el tiempo en que deje de satisfacer dichas obligaciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En el Comité y en la Asamblea Consultiva durante el tiempo en que deje de satisfacer dichas obligaciones</mark></span>Según el <span class=\"ref-norma\">art. 9 del Estatuto del Consejo de Europa</span>: <span class=\"ref-concepto\">\"podrá suspender su derecho de representación en el Comité y en la Asamblea Consultiva durante el tiempo en que deje de satisfacer dichas obligaciones\"</span>. Suspensión temporal por impago. <i>(asterisco ✱ del temario)</i><!--t1m:lote4-->"}]},{"a":"Artículos 13, 14 y 15 — Naturaleza y composición del Comité ✱ R13","q":[{"i":"1-ia-3311","p":"Estatuto del Consejo de Europa, hecho en Londres el 5 de mayo de 1949. El Comité de Ministros. Los representantes en el Comité de Ministros son los Ministros de Asuntos Exteriores; cuando un Ministro de Asuntos Exteriores no pueda asistir, podrá designarse un suplente que actúe en su lugar y que será, en la medida de lo posible:","o":["el embajador del país ante el Consejo de Europa.","un parlamentario de su país.","un miembro del Gobierno de su país.","un alto funcionario del Ministerio de Asuntos Exteriores."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">un miembro del Gobierno de su país</mark></span>El <span class=\"ref-norma\">art. 14 de el Estatuto del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"éste será, en la medida de lo posible, un miembro del Gobierno de su país\"</span>. El suplente será, en lo posible, miembro del Gobierno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-271","p":"Estatuto del Consejo de Europa. Funciones del Comité de Ministros. El Comité de Ministros examinará, por recomendación de la __________ o por iniciativa propia, las medidas adecuadas para realizar la finalidad del Consejo de Europa.","o":["Secretaría","Secretario General","Asamblea Consultiva","Mesa de la Asamblea"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Asamblea Consultiva</mark></span>Según el <span class=\"ref-norma\">art. 15.a) del Estatuto del Consejo de Europa</span>: <span class=\"ref-concepto\">\"El Comité de Ministros examinará, por recomendación de la Asamblea Consultiva o por iniciativa propia, las medidas adecuadas para realizar la finalidad del Consejo de Europa\"</span>. Sus conclusiones podrán revestir la forma de recomendaciones a los Gobiernos. <i>(asterisco ✱ del temario)</i><!--t1m:lote4-->"},{"i":"1-ia-3313","p":"Estatuto del Consejo de Europa, hecho en Londres el 5 de mayo de 1949. El Comité de Ministros. Las conclusiones del Comité de Ministros podrán, si hubiere lugar a ello, revestir la forma de recomendaciones a los Gobiernos, y el Comité podrá invitar a éstos a:","o":["poner en su conocimiento las medidas que han tomado respecto a dichas recomendaciones.","ratificar las recomendaciones en el plazo máximo de un año.","aplicar las recomendaciones mediante su legislación interna.","someter las recomendaciones a la aprobación de sus Parlamentos, en los términos que establezca la propia norma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">poner en su conocimiento las medidas que han tomado respecto a dichas recomendaciones</mark></span>El <span class=\"ref-norma\">art. 15.b de el Estatuto del Consejo de Europa</span> dispone: <span class=\"ref-concepto\">\"El Comité podrá invitar a éstos a poner en su conocimiento las medidas que han tomado respecto a dichas recomendaciones\"</span>. Puede pedir información sobre las medidas adoptadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 19 a 23 — Institución, jueces, elección y mandato ✱ R17","q":[{"i":"1-ia-3448","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Institución del Tribunal. Con el fin de asegurar el respeto de los compromisos que resultan para las Altas Partes Contratantes del Convenio y sus Protocolos, se instituye un Tribunal Europeo de Derechos Humanos que:","o":["se reunirá en sesiones periódicas.","funcionará de manera permanente.","actuará con carácter subsidiario y temporal.","funcionará de manera permanente en Estrasburgo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">funcionará de manera permanente</mark></span>El <span class=\"ref-norma\">art. 19 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"denominado “el Tribunal”. Funcionará de manera permanente\"</span>. El Tribunal funciona de manera permanente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-132","p":"Según la Declaración Universal de los Derechos Humanos, la libertad de opinión y de expresión se recoge en su artículo:","o":["17.","18.","19.","20."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">19</mark></span><span class=\"ref-norma\">Declaración Universal de Derechos Humanos, art. 19</span> dispone: <span class=\"ref-concepto\">\"Todo individuo tiene derecho a la libertad de opinión y de expresión\"</span>. El 17 es la propiedad, el 18 la libertad de pensamiento, conciencia y religión y el 20 la libertad de reunión y asociación."},{"i":"1-ia-3449","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Número de jueces. El Tribunal Europeo de Derechos Humanos se compondrá de un número de Jueces:","o":["igual al de las Altas Partes Contratantes.","igual a la mitad de las Altas Partes Contratantes.","fijado por el Comité de Ministros cada nueve años.","de cuarenta y siete, con independencia del número de Partes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">igual al de las Altas Partes Contratantes</mark></span>El <span class=\"ref-norma\">art. 20 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"El Tribunal se compondrá de un número de Jueces igual al de las Altas Partes Contratantes\"</span>. Un juez por cada Alta Parte Contratante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-286","p":"Convenio para la protección de los Derechos Humanos y de las Libertades Fundamentales. Número de jueces. El Tribunal Europeo de Derechos Humanos se compondrá de un número de Jueces:","o":["Igual al de los Estados miembros de la Unión Europea.","Fijado por la Asamblea Parlamentaria.","Igual a la mitad más uno de las Altas Partes Contratantes.","Igual al de las Altas Partes Contratantes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Igual al de las Altas Partes Contratantes</mark></span>Según el <span class=\"ref-norma\">art. 20 del Convenio Europeo de Derechos Humanos</span>: <span class=\"ref-concepto\">\"El Tribunal se compondrá de un número de Jueces igual al de las Altas Partes Contratantes\"</span>. Artículo 20 del Convenio. <i>(asterisco ✱ del temario)</i><!--t1m:lote4-->"},{"i":"1-179","p":"Convenio para la protección de los Derechos Humanos y de las Libertades Fundamentales. Condiciones para el ejercicio de las funciones de juez. Los candidatos a Juez del Tribunal Europeo de Derechos Humanos deberán ser menores de __________ en la fecha en que la Asamblea Parlamentaria reciba la lista de tres candidatos.","o":["70 años","65 años","60 años","67 años"],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">65 años</mark></span>Según el <span class=\"ref-norma\">art. 21.2 del Convenio Europeo de Derechos Humanos</span>: <span class=\"ref-concepto\">\"Los candidatos deberán ser menores de 65 años en la fecha en que la Asamblea Parlamentaria reciba la lista de tres candidatos\"</span>. Los Jueces deben gozar de la más alta consideración moral y formarán parte del tribunal a título individual. <i>(marca EXOF / sello «PREGUNTA EXAMEN» del temario)</i><!--t1m:lote1-->"},{"i":"1-ia-3735","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Elementos de los crímenes. Podrán proponer enmiendas a los Elementos de los Crímenes cualquier Estado Parte, el fiscal y:","o":["los magistrados, por mayoría de dos tercios.","el Presidente de la Corte, a título individual.","los magistrados, por mayoría absoluta.","la Presidencia de la Asamblea de los Estados Partes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los magistrados, por mayoría absoluta</mark></span>El <span class=\"ref-norma\">art. 9.2 de el Estatuto de Roma</span> dispone: <span class=\"ref-concepto\">\"Los magistrados, por mayoría absoluta\"</span>. Los magistrados proponen por mayoría absoluta; las enmiendas se aprueban por dos tercios de la Asamblea. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-142","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales. Condiciones de ejercicio de sus funciones (PREGUNTA EXAMEN 2020). Los candidatos a Juez del Tribunal Europeo de Derechos Humanos deberán ser menores de 65 años en la fecha en que:","o":["la Asamblea Parlamentaria reciba la lista de tres candidatos.","la Asamblea Parlamentaria elija al candidato por mayoría absoluta.","el Comité de Ministros reciba la lista de tres candidatos.","el candidato sea nombrado por el Presidente del Tribunal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Asamblea Parlamentaria reciba la lista de tres candidatos</mark></span>El <span class=\"ref-norma\">art. 21.2 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"Los candidatos deberán ser menores de 65 años en la fecha en que la Asamblea Parlamentaria reciba la lista de tres candidatos, en virtud del artículo 22\"</span>. El momento es la recepción de la lista de tres candidatos por la Asamblea Parlamentaria."},{"i":"1-ia-3450","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Condiciones de ejercicio de sus funciones. Los candidatos a Juez del Tribunal Europeo de Derechos Humanos deberán ser menores de 65 años en la fecha en que:","o":["la Asamblea Parlamentaria elija al candidato.","el Comité de Ministros reciba la propuesta del Estado, salvo que se disponga otra cosa en la normativa aplicable.","el candidato tome posesión de su cargo.","la Asamblea Parlamentaria reciba la lista de tres candidatos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la Asamblea Parlamentaria reciba la lista de tres candidatos</mark></span>El <span class=\"ref-norma\">art. 21.1 y 2 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"menores de 65 años en la fecha en que la Asamblea Parlamentaria reciba la lista de tres candidatos\"</span>. La edad se computa a la fecha de recepción de la lista de tres candidatos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3452","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Elección de los jueces. Los Jueces del Tribunal Europeo de Derechos Humanos serán elegidos por la Asamblea Parlamentaria en razón de cada Alta Parte Contratante, por mayoría absoluta de votos, de una lista de:","o":["tres candidatos propuesta por el Comité de Ministros.","tres candidatos presentada por esa Alta Parte Contratante.","cinco candidatos presentada por esa Alta Parte Contratante.","dos candidatos presentada por esa Alta Parte Contratante."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tres candidatos presentada por esa Alta Parte Contratante</mark></span>El <span class=\"ref-norma\">art. 22 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"por mayoría absoluta de votos, de una lista de tres candidatos presentada por esa Alta Parte Contratante\"</span>. Elige la Asamblea Parlamentaria por mayoría absoluta, de una lista de tres candidatos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-112","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales. Tribunal Europeo de Derechos Humanos. Duración del mandato y revocación. Los jueces serán elegidos por un periodo de ___. No serán reelegibles.","o":["Cuatro años.","Cinco años.","Seis años.","Nueve años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Nueve años.</mark></span>El <span class=\"ref-norma\">art. 23.1 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"Los jueces serán elegidos por un periodo de nueve años. No serán reelegibles\"</span>."},{"i":"1-ia-3453","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Duración del mandato y revocación. Los jueces del Tribunal Europeo de Derechos Humanos serán elegidos por un periodo de:","o":["nueve años, sin posibilidad de reelección.","nueve años, reelegibles por un solo periodo.","seis años, renovables por un periodo igual.","doce años, sin posibilidad de reelección."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">nueve años, sin posibilidad de reelección</mark></span>El <span class=\"ref-norma\">art. 23.1 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"Los jueces serán elegidos por un periodo de nueve años. No serán reelegibles\"</span>. Nueve años y no reelegibles. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-143","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales. Pleno del Tribunal (EX). El Tribunal, reunido en pleno, elegirá, por un período de tres años, a su Presidente y a uno o dos Vicepresidentes, que serán:","o":["reelegibles.","no reelegibles.","reelegibles por una sola vez.","reelegibles con la aprobación de la Asamblea Parlamentaria."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">reelegibles</mark></span>El <span class=\"ref-norma\">art. 25.a) de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"Elegirá, por un período de tres años, a su Presidente y a uno o dos Vicepresidentes, que serán reelegibles\"</span>. Son reelegibles (frente a los jueces, que no lo son)."},{"i":"1-ia-3455","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Duración del mandato y revocación. Un juez del Tribunal Europeo de Derechos Humanos sólo podrá ser relevado de sus funciones si los demás jueces deciden:","o":["por mayoría absoluta, que dicho juez ha incumplido gravemente los deberes de su cargo.","por unanimidad, que dicho juez ha dejado de reunir las condiciones requeridas para serlo.","por mayoría de dos tercios, que dicho juez ha dejado de reunir las condiciones requeridas para serlo.","por mayoría de tres cuartos, que dicho juez ha cometido una falta disciplinaria muy grave, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por mayoría de dos tercios, que dicho juez ha dejado de reunir las condiciones requeridas para serlo</mark></span>El <span class=\"ref-norma\">art. 23.3 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"si los demás jueces deciden, por mayoría de dos tercios, que dicho juez ha dejado de reunir las condiciones requeridas para serlo\"</span>. El relevo exige dos tercios de los demás jueces. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3454","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Duración del mandato y revocación. Los jueces del Tribunal permanecerán en sus funciones hasta su sustitución y, no obstante:","o":["dejarán de conocer de los asuntos pendientes de resolución.","continuarán conociendo únicamente de los asuntos de la Gran Sala.","cesarán inmediatamente al cumplirse los 70 años de edad.","continuarán conociendo de los asuntos que tengan ya asignados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">continuarán conociendo de los asuntos que tengan ya asignados</mark></span>El <span class=\"ref-norma\">art. 23.2 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"No obstante, continuarán conociendo de los asuntos que tengan ya asignados\"</span>. Siguen con los asuntos ya asignados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 26 · FORMACIONES DEL TRIBUNAL","q":[{"i":"1-287","p":"Convenio para la protección de los Derechos Humanos y de las Libertades Fundamentales. Formaciones del Tribunal. Para el examen de los asuntos que se le sometan, el Tribunal actuará en formación de:","o":["Juez único, en Comités compuestos por cinco jueces, en Salas de siete jueces y en una Gran Sala de diecisiete jueces.","Juez único, en Comités compuestos por tres jueces, en Salas de cinco jueces y en una Gran Sala de nueve jueces.","Juez único, en Comités compuestos por tres jueces, en Salas de siete jueces y en una Gran Sala de diecisiete jueces.","Comités compuestos por tres jueces, en Salas de siete jueces y en una Gran Sala de quince jueces."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Juez único, en Comités compuestos por tres jueces, en Salas de siete jueces y en una Gran Sala de diecisiete jueces</mark></span>Según el <span class=\"ref-norma\">art. 26.1 del Convenio Europeo de Derechos Humanos</span>: <span class=\"ref-concepto\">\"el Tribunal actuará en formación de juez único, en Comités compuestos por tres jueces, en Salas de siete jueces y en una Gran Sala de diecisiete jueces\"</span>. Las Salas constituyen los Comités por un período determinado. <i>(asterisco ✱ del temario)</i><!--t1m:lote4-->"},{"i":"1-ia-3459","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Formación de juez único, comités, salas y Gran Sala. Para el examen de los asuntos que se le sometan, el Tribunal actuará en formación de juez único, en Comités compuestos por tres jueces, en Salas de siete jueces y en una Gran Sala de:","o":["quince jueces.","nueve jueces.","diecisiete jueces.","veintiún jueces, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">diecisiete jueces</mark></span>El <span class=\"ref-norma\">art. 26.1 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"en una Gran Sala de diecisiete jueces\"</span>. La Gran Sala se compone de diecisiete jueces. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3460","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Formación de juez único, comités, salas y Gran Sala. Los Comités del Tribunal Europeo de Derechos Humanos, compuestos por tres jueces, son constituidos por un periodo determinado por:","o":["el Tribunal reunido en pleno.","las Salas del Tribunal.","el Presidente del Tribunal.","la Gran Sala del Tribunal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las Salas del Tribunal</mark></span>El <span class=\"ref-norma\">art. 26.1 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"constituirán los Comités por un periodo determinado\"</span>. El Pleno constituye las Salas y las Salas constituyen los Comités. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3461","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Formación de juez único, comités, salas y Gran Sala. Cuando el Pleno del Tribunal así lo solicite, el Comité de Ministros podrá, por decisión unánime y por un periodo determinado, reducir el número de jueces de las Salas a:","o":["cinco.","tres.","seis.","cuatro."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cinco</mark></span>El <span class=\"ref-norma\">art. 26.2 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"reducir a cinco el número de jueces de las Salas\"</span>. Se reduce a cinco por decisión unánime del Comité de Ministros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3462","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Formación de juez único, comités, salas y Gran Sala. Cuando el Tribunal actúe en formación de juez único, ningún juez podrá examinar una solicitud:","o":["presentada por nacionales del Estado en cuya representación fue elegido, salvo que se disponga otra cosa en la normativa aplicable.","que haya sido ya examinada por otro juez único de su misma nacionalidad.","referida a la Alta Parte Contratante de su residencia habitual.","contra la Alta Parte Contratante en cuya representación fue elegido dicho juez."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">contra la Alta Parte Contratante en cuya representación fue elegido dicho juez</mark></span>El <span class=\"ref-norma\">art. 26.3 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"ningún juez podrá examinar una solicitud contra la Alta Parte Contratante en cuya representación fue elegido dicho juez\"</span>. El juez único no puede examinar demandas contra el Estado que representa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3463","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Formación de juez único, comités, salas y Gran Sala. El juez elegido en representación de una Alta Parte Contratante en el litigio será miembro de pleno derecho de la Sala y de la Gran Sala; en su ausencia, actuará en calidad de juez:","o":["el juez de mayor antigüedad designado por el Presidente de la Sala correspondiente, conforme al procedimiento que se establezca reglamentariamente.","un juez ad hoc elegido por la Asamblea Parlamentaria a propuesta de esa Parte.","una persona designada por el Presidente del Tribunal a partir de una lista presentada previamente por esa Parte.","el Vicepresidente del Tribunal designado conforme al reglamento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">una persona designada por el Presidente del Tribunal a partir de una lista presentada previamente por esa Parte</mark></span>El <span class=\"ref-norma\">art. 26.4 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"actuará en calidad de juez una persona designada por el Presidente del Tribunal a\"</span>. La designa el Presidente del Tribunal de entre una lista presentada por esa Parte. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3464","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Formación de juez único, comités, salas y Gran Sala. Formarán también parte de la Gran Sala el Presidente del Tribunal, los Vicepresidentes, los Presidentes de las Salas y:","o":["los jueces elegidos por la Asamblea Parlamentaria para esa función, sin perjuicio de lo dispuesto en otras disposiciones.","demás jueces designados de conformidad con el reglamento del Tribunal.","los jueces de mayor antigüedad en el Tribunal reunido en pleno.","los jueces que determine el Comité de Ministros en cada caso."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">demás jueces designados de conformidad con el reglamento del Tribunal</mark></span>El <span class=\"ref-norma\">art. 26.5 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"demás jueces designados de conformidad con el reglamento del Tribunal\"</span>. Los demás jueces se designan conforme al reglamento del Tribunal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 35 · ADMISIBILIDAD DE LAS DEMANDAS INDIVIDUALES · EL TRIBUNAL","q":[{"i":"1-293","p":"Convenio para la protección de los Derechos Humanos y de las Libertades Fundamentales. Condiciones de admisibilidad. El Tribunal no admitirá ninguna demanda individual presentada en virtud del artículo 34 cuando:","o":["Sea anónima, o haya sido presentada por una organización no gubernamental sin autorización de su Estado.","Sea esencialmente la misma que una demanda examinada anteriormente por el Tribunal, aunque contenga hechos nuevos.","Sea anónima, o sea esencialmente la misma que una demanda examinada anteriormente por el Tribunal o ya sometida a otra instancia internacional y no contenga hechos nuevos.","No haya sido presentada por un abogado colegiado en una de las Altas Partes Contratantes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Sea anónima, o sea esencialmente la misma que una demanda examinada anteriormente por el Tribunal o ya sometida a otra instancia internacional y no contenga hechos nuevos</mark></span>Según el <span class=\"ref-norma\">art. 35.2 del Convenio Europeo de Derechos Humanos</span>: <span class=\"ref-concepto\">\"sea esencialmente la misma que una demanda examinada anteriormente por el Tribunal\"</span>. Artículo 35.2 del Convenio. <i>(asterisco ✱ del temario)</i><!--t1m:lote5-->"},{"i":"1-ia-3474","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Condiciones de admisibilidad. Al Tribunal no podrá recurrirse sino después de agotar las vías de recursos internas, tal como se entiende según los principios de derecho internacional generalmente reconocidos y en el plazo de:","o":["seis meses a partir de la fecha de la resolución interna definitiva.","cuatro meses a partir de la fecha en que se tuvo conocimiento de la violación.","un año a partir de la fecha de la resolución interna definitiva.","cuatro meses a partir de la fecha de la resolución interna definitiva."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cuatro meses a partir de la fecha de la resolución interna definitiva</mark></span>El <span class=\"ref-norma\">art. 35.1 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"y en el plazo de cuatro meses a partir de la fecha de la resolución interna definitiva\"</span>. El plazo, tras la reforma del Protocolo 15, es de cuatro meses desde la resolución interna definitiva. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3475","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Condiciones de admisibilidad. El Tribunal no admitirá ninguna demanda individual cuando sea anónima o cuando:","o":["haya sido ya examinada por los tribunales nacionales, aunque se alegue una violación nueva de derechos, conforme al procedimiento que se establezca reglamentariamente.","sea presentada por una persona jurídica de Derecho público contra el Estado.","sea esencialmente la misma que una demanda examinada anteriormente por el Tribunal o ya sometida a otra instancia internacional, y no contenga hechos nuevos.","se refiera a hechos anteriores a la entrada en vigor del Convenio en el Estado demandado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">sea esencialmente la misma que una demanda examinada anteriormente por el Tribunal o ya sometida a otra instancia internacional, y no contenga hechos nuevos</mark></span>El <span class=\"ref-norma\">art. 35.2 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"sea esencialmente la misma que una demanda examinada anteriormente por el Tribunal o ya so-metida a otra instancia internacional de investigación o de arreglo, y no contenga hechos nuevos\"</span>. Inadmite la demanda anónima y la esencialmente idéntica a otra ya examinada, sin hechos nuevos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3476","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Condiciones de admisibilidad. El Tribunal declarará inadmisible cualquier demanda individual si considera que el demandante no ha sufrido un perjuicio importante, a menos que:","o":["el Estado demandado lo solicite expresamente al Tribunal en el trámite de admisibilidad.","el respeto de los derechos humanos garantizados por el Convenio y por sus Protocolos exija un examen del fondo de la demanda.","la demanda haya sido examinada previamente por un tribunal interno sin motivación suficiente, sin perjuicio de lo dispuesto en otras disposiciones.","el perjuicio alegado sea de carácter moral y afecte a un derecho fundamental del demandante."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el respeto de los derechos humanos garantizados por el Convenio y por sus Protocolos exija un examen del fondo de la demanda</mark></span>El <span class=\"ref-norma\">art. 35.3 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"a menos que el respeto de los derechos humanos garantizados por el Convenio y por sus Protocolos exija un examen del fondo de la demanda\"</span>. La excepción es que el respeto de los derechos humanos exija examinar el fondo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-3477","p":"Convenio para la Protección de los Derechos Humanos y de las Libertades Fundamentales (Convenio Europeo de Derechos Humanos). Condiciones de admisibilidad. El Tribunal rechazará cualquier demanda que considere inadmisible en aplicación del Convenio y podrá decidirlo así:","o":["en cualquier fase del procedimiento.","únicamente en la fase de admisibilidad.","antes de dar traslado de la demanda al Estado.","hasta que se dicte sentencia sobre el fondo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en cualquier fase del procedimiento</mark></span>El <span class=\"ref-norma\">art. 35.4 de el Convenio Europeo de Derechos Humanos</span> dispone: <span class=\"ref-concepto\">\"Podrá decidirlo así en cualquier fase del procedimiento\"</span>. La inadmisibilidad puede apreciarse en cualquier fase. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 8 y 10 — Impuestos y fondos (disposiciones monetarias) ✱ R31","q":[{"i":"1-ia-4041","p":"Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional. Exención de impuestos, derechos de aduana y restricciones de importación o exportación. La Corte, sus haberes, ingresos y otros bienes, así como sus operaciones y transacciones, estarán exentos de todos los impuestos directos; sin embargo, la Corte no podrá reclamar la exención del pago de:","o":["los gravámenes que constituyan de hecho la remuneración de servicios públicos prestados a una tarifa fija según la cantidad de servicios prestados.","los impuestos indirectos incluidos en el precio de los bienes y servicios que adquiera, en los términos que establezca la propia norma, salvo que se disponga otra cosa en la normativa aplicable.","las tasas por la expedición de licencias, permisos y autorizaciones administrativas.","los derechos de aduana sobre los artículos que importe para su uso oficial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los gravámenes que constituyan de hecho la remuneración de servicios públicos prestados a una tarifa fija según la cantidad de servicios prestados</mark></span>El <span class=\"ref-norma\">art. 8.1 de el Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"la Corte no podrá reclamar la exención del pago de los gravámenes que constituyan de hecho la remuneración de servicios públicos\"</span>. Debe pagar las tarifas por servicios públicos identificables y desglosables. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-ia-4227","p":"Acuerdo sobre los privilegios e inmunidades de la Corte Penal Internacional. Exención de impuestos. La Corte, sus haberes, ingresos y otros bienes, así como sus operaciones y transacciones, estarán exentos de:","o":["todos los impuestos indirectos.","las tasas por servicios públicos.","todos los impuestos directos.","los impuestos sobre el consumo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">todos los impuestos directos</mark></span>El <span class=\"ref-norma\">art. 8.1 de la Acuerdo sobre los privilegios e inmunidades de la CPI</span> dispone: <span class=\"ref-concepto\">\"estarán exentos de todos los impuestos directos\"</span> Todos los impuestos directos."},{"i":"1-199","p":"Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional. Exención de impuestos, derechos de aduana y restricciones de importación o exportación. La Corte estará exenta de:","o":["Derechos de aduana e impuestos indirectos sobre toda importación, incluidas las destinadas al uso personal de su personal.","Derechos de aduana, impuestos sobre el volumen de las importaciones y prohibiciones o restricciones respecto de los artículos que importe o exporte para su uso oficial y respecto de sus publicaciones.","Impuestos sobre el volumen de las importaciones, pero no de las prohibiciones o restricciones sobre sus publicaciones.","Derechos de aduana, salvo respecto de los artículos que importe o exporte para su uso oficial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Derechos de aduana, impuestos sobre el volumen de las importaciones y prohibiciones o restricciones respecto de los artículos que importe o exporte para su uso oficial y respecto de sus publicaciones</mark></span>Según el <span class=\"ref-norma\">art. 8.2 (R31) del Acuerdo sobre Privilegios e Inmunidades de la CPI</span>: <span class=\"ref-concepto\">\"La Corte estará exenta de derechos de aduana\"</span>. Ficha RECUERDA R31. <i>(ficha RECUERDA R31 del temario)</i><!--t1m:lote1-->"},{"i":"1-ia-4046","p":"Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional. Fondos y exención de restricciones monetarias. La Corte no quedará sometida a controles financieros, reglamentos o moratorias financieros de índole alguna en el desempeño de sus funciones y podrá tener fondos, moneda de cualquier tipo u oro y:","o":["operar cuentas únicamente en euros.","operar cuentas previa autorización del Estado Parte.","operar cuentas en la moneda del Estado de la sede.","operar cuentas en cualquier moneda."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">operar cuentas en cualquier moneda</mark></span>El <span class=\"ref-norma\">art. 10.1 de el Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"Tener fondos, moneda de cualquier tipo u oro y operar cuentas en cualquier moneda\"</span>. Puede operar cuentas en cualquier moneda. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-87","p":"Estatuto de Roma de la Corte Penal Internacional, hecho en Roma el 17 de julio de 1998. Disposiciones monetarias. La Corte no quedará sometida a controles financieros, reglamentos o moratorias financieros de índole alguna en el desempeño de sus funciones y podrá: señale la INCORRECTA.","o":["Recibir, tener, negociar, transferir o convertir bonos u otros títulos financieros o realizar cualquier transacción con ellos.","Las transacciones financieras de la Corte gozarán, en cuanto al tipo de cambio, de un trato menos favorable que el que otorgue el Estado Parte de que se trate a cualquier organización intergubernamental o misión diplomática.","Transferir libremente sus fondos, oro o moneda de un país a otro o dentro de un país y convertir a cualesquiera otras las monedas que tenga en su poder.","Tener fondos, moneda de cualquier tipo u oro y operar cuentas en cualquier moneda."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las transacciones financieras de la Corte gozarán, en cuanto al tipo de cambio, de un trato menos favorable que el que otorgue el Estado Parte de que se trate a cualquier organización intergubernamental o misión diplomática</mark></span>La opción B es la INCORRECTA porque dice «menos favorable». Ojo: esta disposición es del Acuerdo sobre Privilegios e Inmunidades, no del Estatuto de Roma. Según el <span class=\"ref-norma\">art. 10.1.d) del Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional</span>: <span class=\"ref-concepto\">\"Las transacciones financieras de la Corte gozarán, en cuanto al tipo de cambio, de un trato no menos favorable que el que otorgue el Estado Parte de que se trate a cualquier organización intergubernamental o misión diplomática.\"</span> (verificado con el texto del temario)."},{"i":"1-ia-4047","p":"Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional. Fondos y exención de restricciones monetarias. Las transacciones financieras de la Corte gozarán, en cuanto al tipo de cambio, de un trato:","o":["igual al que otorgue el Estado Parte de que se trate a las entidades financieras nacionales, conforme al procedimiento que se establezca reglamentariamente.","preferente respecto del que otorgue el Estado Parte a cualquier organización internacional.","no menos favorable que el que otorgue el Estado Parte de que se trate a cualquier organización intergubernamental o misión diplomática.","no menos favorable que el que otorgue el Estado Parte a las empresas públicas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no menos favorable que el que otorgue el Estado Parte de que se trate a cualquier organización intergubernamental o misión diplomática</mark></span>El <span class=\"ref-norma\">art. 10.1.d de el Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"gozarán, en cuanto al tipo de cambio, de un trato no\"</span>. El trato no puede ser menos favorable que el de organizaciones intergubernamentales o misiones diplomáticas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"1-161","p":"Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional, hecho en Nueva York el 9 de septiembre de 2002. Fondos y exención de restricciones monetarias (EXAMEN 2020). Las transacciones financieras de la Corte gozarán, en cuanto al tipo de cambio, de un trato no menos favorable que el que otorgue el Estado Parte de que se trate a:","o":["cualquier organización intergubernamental o misión diplomática.","cualquier organización internacional o misión consular.","cualquier entidad financiera o misión diplomática.","las organizaciones no gubernamentales acreditadas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cualquier organización intergubernamental o misión diplomática</mark></span>El <span class=\"ref-norma\">art. 10.1 de el Acuerdo sobre Privilegios e Inmunidades de la Corte Penal Internacional</span> dispone: <span class=\"ref-concepto\">\"Las transacciones financieras de la Corte gozarán, en cuanto al tipo de cambio, de un trato no menos favorable que el que otorgue el Estado Parte de que se trate a cualquier organización intergubernamental o misión diplomática\"</span>. No menos favorable que el de cualquier organización intergubernamental o misión diplomática."}]}];
